const einwStand = () => ({ an: true, gesehen: {}, ...(INIT?.einstellungen?.einweisung || {}) });
// 2.6.1 (Prüfung, Regel 11): Speichern abwarten – schlägt es fehl, alter Stand zurück und Meldung (nicht still „gespeichert“)
async function einwSpeichern(neu) {
  if (!INIT) return false;
  const vorher = einwStand(), w = { ...vorher, ...neu };
  INIT.einstellungen = { ...(INIT.einstellungen || {}), einweisung: w };
  try { await einstSpeichern("einweisung", w); return true; }
  catch (e) { INIT.einstellungen.einweisung = vorher; einwSchalterZeigen(); meldeFehler(e); return false; }
}
// 2.6.1 (Prüfung): wer eine Karte an 3 verschiedenen Tagen gesehen, aber nie „Verstanden“ getippt hat, bekommt sie nicht mehr
// (sonst bliebe z. B. der Tipp des Tages für immer zurückgehalten). Gezählt nur auf diesem Gerät.
const EINW_TAGE = 3, EINW_GEZEIGT = "kc_club_einw_gezeigt";
const einwGezeigt = () => { try { return JSON.parse(localStorage.getItem(EINW_GEZEIGT) || "{}") || {}; } catch { return {}; } };
function einwTagMerken(v) { const g = einwGezeigt(), t = heuteIso(), l = g[v] || []; if (!l.includes(t)) { g[v] = [...l, t].slice(-EINW_TAGE); try { localStorage.setItem(EINW_GEZEIGT, JSON.stringify(g)); } catch {} } }
function einwOffen(v) {
  const st = einwStand(), e = EINWEISUNG.find((x) => x.id === v), tage = einwGezeigt()[v] || [];
  if (tage.length >= EINW_TAGE && !tage.includes(heuteIso())) return false;
  return !!(INIT && ICH && st.an && e && !st.gesehen?.[v] && (!e.nur || e.nur()));
}
function einwKarteWeg() { const k = document.querySelectorAll(".einw-karte"); if (k.length) { vorlesenStopp(); k.forEach((x) => x.remove()); } }
function einwZeigen(v) {
  const sek = $("v-" + v);
  if (sek && einwOffen(v) && sek.querySelector(`:scope > .einw-karte[data-v="${v}"]`)) return; // schon da – nicht neu bauen
  einwKarteWeg();
  if (!sek || !einwOffen(v)) return;
  const tpl = document.createElement("template"); tpl.innerHTML = einwHtml(v); const k = tpl.content.firstElementChild; if (!k) return;
  const nach = sek.querySelector(":scope > .kopf2, :scope > .hero"); nach ? nach.after(k) : sek.prepend(k);
}
// 2.22.9: gleiche Karte als HTML – auch oben in Fenstern (Registry-Einträge mit blatt: true, z. B. einwHtml("b-stadt"))
function einwHtml(v) {
  if (!einwOffen(v)) return "";
  einwTagMerken(v);
  const e = EINWEISUNG.find((x) => x.id === v);
  return `<div class="karte einw-karte vorlese-karte" role="note" data-v="${v}"><div class="einw-kopf">🎓 Kurz erklärt ${VORLESE_KNOPF}</div><h3>${e.sym} ${esc(e.t)}</h3><p>${typeof e.x === "function" ? e.x() : e.x}</p>
    <div class="knoepfe"><button class="knopf haupt klein" onclick="einwVerstanden('${v}')">👍 Verstanden</button><button class="knopf klein" onclick="einwAlleAus()">Keine Einweisungen mehr</button></div></div>`;
}
function einwVerstanden(v) { einwKarteWeg(); einwSpeichern({ gesehen: { ...einwStand().gesehen, [v]: new Date().toISOString() } }); }
async function einwAlleAus() { einwKarteWeg(); if (await einwSpeichern({ an: false })) { einwSchalterZeigen(); melde("🎓 Keine Einweisungen mehr – wieder einschalten unter ⚙️ Mehr → Einstellungen"); } }
async function einwSchalter(an) { if (await einwSpeichern({ an })) melde(an ? "🎓 Einweisungen sind an" : "🎓 Einweisungen sind aus"); }
async function einwZuruecksetzen() { try { localStorage.removeItem(EINW_GEZEIGT); } catch {} if (await einwSpeichern({ an: true, gesehen: {} })) { einwSchalterZeigen(); einwZeigen(aktuelleAnsicht); melde("🎓 Alle Einweisungen kommen beim nächsten Öffnen der Bereiche wieder"); } }
function einwSchalterZeigen() { if ($("setEinw")) $("setEinw").checked = einwStand().an; }

