  "termine": ["e:termine", "t:antwort_zurueck", "t:mitfahren", "t:private_termine", "h:wiederholen", "h:todo", "h:terminanfrage", "h:terminfindung", "h:kalender_blaettern", "h:drucken", "t:kalender", "h:naechstes_treffen", "h:feiertage"],
