  "mitglied": ["e:mitglieder", "t:anklopfen", "h:wer_online", "h:gratulieren", "h:kontakt_teilen"],
  "pinnwand": ["e:pinnwand", "h:pinnwand_antwort", "h:pinnwand_wichtig", "h:pinnwand_alt", "h:hilfe_absprache"],
