const ANSAGE_SAMMEL_MS = 1500, ANSAGE_NAMEN_MAX = 3;
function onlineAnsageText(n) {
  if (n.length > ANSAGE_NAMEN_MAX) return `${n.length} Clubkameradinnen und Kameraden sind gerade online`;
  return n.length === 1 ? `${n[0]} ist jetzt online` : `${n.slice(0, -1).join(", ")} und ${n[n.length - 1]} sind jetzt online`;
}
function onlineAnsageSprechen(namen) {
  if (document.hidden || inRuheJetzt(INIT?.einstellungen?.ruhezeit)) return;
  const jetzt = Date.now(), n = [...new Set(namen.filter(Boolean))].filter((x) => jetzt - (OA.gesagt.get(x) || 0) >= ANSAGE_PAUSE_MS);
  if (!n.length) return;
  n.forEach((x) => OA.gesagt.set(x, jetzt));
  OA.warte = [...new Set([...(OA.warte || []), ...n])];
  clearTimeout(OA.sammelTimer);
  OA.sammelTimer = setTimeout(() => {
    const alle = OA.warte || []; OA.warte = []; if (!alle.length || document.hidden) return;
    const ton = anmeldeTonAn(); if (ton) anmeldeTon();
    if (ansageAn()) setTimeout(() => sprechen(onlineAnsageText(alle)), ton ? 700 : 0);
  }, ANSAGE_SAMMEL_MS);
}
// KC-CLUB-STIMME (2.6.2, Fund Hansi: „auf dem iPad hört sich das Vorlesen schrecklich an“): Apple liefert unter Deutsch auch
// Spaß- und Roboterstimmen (Eloquence/Novelty: Eddy, Flo, Grandma, Rocko, Zarvox …) – vorher nahm die App einfach die erste.
