// Chat: alle 4 s neu laden, wenn jemand aus dem Gespräch online ist – sonst alle 12 s
// 2-s-Takt (0.54.0): schreibt gerade jemand → jedes Mal; jemand online → alle 4 s; sonst alle 12 s (wie bisher)
const CHAT_TAKT_MS = 2000;
// KC-CLUB-SPARTAKT (2.23.9, Prüfung „Server-Aufrufe“): Grundtakt 2 s bleibt nur, solange jemand tippt. Ist der andere online und
// es wurde in den letzten 90 s geschrieben → alle 4 s, sonst alle 8 s; niemand da → 12 s, mit Push (neue Nachrichten kommen ohnehin
// sofort per Push) 20 s. Im Hintergrund gar nicht – beim Zurückholen lädt die App den Chat sowieso neu.
let CHAT_AKTIV = 0;
function chatTakt() {
  ONL.takt++;
  if (chatTakt.laeuft || document.hidden) return;
  const jemandDa = (CHAT?.teilnehmer || []).some((t) => t.person_id !== ICH?.person_id && ONL.ids.has(t.person_id));
  const frisch = Date.now() - CHAT_AKTIV < 90000, ruhig = PUSH_AKTIV ? 10 : 6;
  if (!(CHAT?.tippt?.length || (jemandDa && ONL.takt % (frisch ? 2 : 4) === 0) || ONL.takt % ruhig === 0)) return;
  chatTakt.laeuft = true; chatLaden(false).finally(() => { chatTakt.laeuft = false; });
}
// KC-CLUB-TIPPT (0.54.0): beim Tippen höchstens alle 3 s „ich schreibe“ melden, Feld leer → sofort aus.
// Wer die Online-Anzeige ausgeschaltet hat (Privatsphäre), meldet auch kein „schreibt …“.
// KC-CLUB-LIVETIPPEN (0.56.0): wer es selbst einschaltet, schickt den Entwurf mit (höchstens 1× je Sekunde, letzter Stand kommt nach)
const LIVE_TIPPEN_ZEICHEN = 300, LIVE_ANZEIGE_ZEICHEN = 140;
const liveTippen = () => !!INIT?.einstellungen?.live_tippen?.an;
let TIPP = { zuletzt: 0, id: null, nach: null };
function tippenMelden() {
  if (!chatId || !ONL.zeigen) return;
  const text = $("text").value;
  if (!text.trim()) return tippenAus();
  const live = liveTippen(), abstand = live ? 1000 : 3000;
  clearTimeout(TIPP.nach);
  if (TIPP.id === chatId && Date.now() - TIPP.zuletzt < abstand) { if (live) TIPP.nach = setTimeout(tippenMelden, abstand); return; }
  // KC-CLUB-TEMPO (2.115.0, Tempo-Log 08.10.: bei langsamem Netz 6 „tippen“ gleichzeitig, je 2–8 s – danach waren Chat und Senden
  // 7–8 s langsam): nie mehr als eine Meldung unterwegs; der letzte Stand geht hinterher, sobald die vorige angekommen ist
  if (TIPP_UNTERWEGS) { TIPP_NOCHMAL = true; return; }
  TIPP = { zuletzt: Date.now(), id: chatId, nach: null }; CHAT_AKTIV = Date.now(); // KC-CLUB-SPARTAKT
  TIPP_UNTERWEGS = true;
  api("tippen", { id: chatId, ...(live ? { text: [...text].slice(-LIVE_TIPPEN_ZEICHEN).join("") } : {}) }).catch(() => {})
    .finally(() => { TIPP_UNTERWEGS = false; if (TIPP_NOCHMAL) { TIPP_NOCHMAL = false; if (live) tippenMelden(); } });
}
let TIPP_UNTERWEGS = false, TIPP_NOCHMAL = false;
// KC-CLUB-CHAT-ABSTAND (1.11.0, Wunsch Hansi): letzte Nachricht stößt nicht mehr unten an – Abstand = gemessene Höhe
// des Eingabebereichs (+ untere Leiste) + etwas Luft; passt sich an, wenn Antwort-/Emoji-/Aufnahmeleiste dazukommt.
function chatAbstand() {
  if ($("chatKopf")) document.documentElement.style.setProperty("--chatKopfHoehe", Math.ceil($("chatKopf").getBoundingClientRect().height + 12) + "px"); // 1.20.1
  const e = $("eingabe"); if (!e || e.classList.contains("versteckt")) return;
  const c = $("chat"); if (!c) return;
  // Platz, den die Seite unter dem Chat ohnehin hat (z. B. für die untere Leiste), nicht doppelt rechnen
  const rest = Math.max(0, document.documentElement.scrollHeight - (c.getBoundingClientRect().bottom + window.scrollY));
  const unten = Math.max(0, window.innerHeight - e.getBoundingClientRect().top);
  document.documentElement.style.setProperty("--chatUnten", Math.max(40, Math.ceil(unten + 18 - rest)) + "px");
  document.documentElement.style.setProperty("--eingabeHoehe", Math.ceil(unten) + "px");
}
if (window.ResizeObserver) document.addEventListener("DOMContentLoaded", () => { const e = $("eingabe"); if (e) new ResizeObserver(chatAbstand).observe(e); });
window.addEventListener("resize", chatAbstand);
// ---------- KC-CLUB-ENTWURF (1.12.0, Wunsch Hansi): halb geschriebener Text bleibt je Chat erhalten (nur auf diesem Gerät) ----------
const entwurfSchluessel = () => "kc_club_entwurf_" + (ICH?.person_id || "x");
function entwurfAlle() { try { const d = JSON.parse(localStorage.getItem(entwurfSchluessel()) || "{}"); return d && typeof d === "object" ? d : {}; } catch { return {}; } }
let entwurfTimer = null;
function entwurfMerken() {
  if (!chatId) return; const id = chatId;
  clearTimeout(entwurfTimer);
  entwurfTimer = setTimeout(() => {
    const d = entwurfAlle(), t = $("text").value;
    if (t.trim()) d[id] = t.slice(0, 4000); else delete d[id];
    const k = Object.keys(d); if (k.length > 50) delete d[k[0]];
    try { localStorage.setItem(entwurfSchluessel(), JSON.stringify(d)); } catch {}
  }, 400);
}
function entwurfLaden(id) {
  clearTimeout(entwurfTimer);
  const t = $("text"); if (!t) return;
  t.value = entwurfAlle()[id] || ""; t.style.height = "auto"; if (t.value) t.style.height = t.scrollHeight + "px";
  entwurfMarkeZeigen();
}
// KC-CLUB-GRUPPE-FARBEN (1.21.1): feste Farbe je Absender (aus dem Namen errechnet, bleibt immer gleich) – hell / dunkel
// Jeder in der Gruppe bekommt eine andere Farbe (Reihenfolge nach Name, bleibt im Chat gleich). Rot zuletzt – eigene Blasen sind rot.
const GRUPPEN_FARBEN = [["#1f618d", "#82b8ff"], ["#1e8449", "#7bd88f"], ["#7d3c98", "#d7a6f5"], ["#b9770e", "#ffc46b"], ["#117a65", "#5fd3bd"], ["#ad1457", "#ff8ac0"], ["#a04000", "#ffab73"], ["#2e4053", "#b8c7dc"], ["#6d4c41", "#d7b49e"], ["#c0392b", "#ff8a80"]];
function gruppenFarbe(name) {
  const namen = [...new Set((CHAT?.teilnehmer || []).filter((t) => t.person_id !== ICH?.person_id).map((t) => t.name))].sort((a, b) => a.localeCompare(b, "de"));
  let i = namen.indexOf(name);
  if (i < 0) { i = 0; for (const c of String(name || "")) i = (i * 31 + c.codePointAt(0)) >>> 0; } // ausgetreten → feste Farbe aus dem Namen
  const [hell, dunkel] = GRUPPEN_FARBEN[i % GRUPPEN_FARBEN.length]; return `--pf:${hell};--pfd:${dunkel}`;
}
// KC-CLUB-ENTWURF-ANZEIGE (1.21.0, Wunsch Hansi): steht Text im Feld, der noch nicht gesendet ist → „✏️ Entwurf“
function entwurfMarkeZeigen() { const t = $("text"), m = $("entwurfMarke"); if (t && m) m.classList.toggle("versteckt", !t.value.trim()); $("textLeerenKnopf")?.classList.toggle("versteckt", !t?.value); sprungHinweisZeigen(); }
// KC-CLUB-EINGABE-LEEREN (2.148.0, Wunsch Hansi): rotes ✕ im Schreibfeld – löscht nur den noch nicht gesendeten Text (und dessen Entwurf), nichts im Chat
function textLeeren() {
  const t = $("text"); if (!t) return;
  clearTimeout(entwurfTimer); if (chatId) entwurfWeg(chatId);
  t.value = ""; t.style.height = "auto"; entwurfMarkeZeigen();
  try { naErwPruefen(); } catch {}
  try { t.focus(); } catch {}
}
// 2.23.99: steht ein App-Sprung im Entwurf, sagen wir, dass daraus nach dem Senden ein Knopf wird (im Schreibfeld geht nur Text)
function sprungHinweisZeigen() {
  const t = $("text"), h = $("sprungHinweis"); if (!t || !h) return;
  const ziele = [...t.value.matchAll(SPRUNG_RE)].map((m) => sprungDef(m[1])).filter(Boolean);
  h.classList.toggle("versteckt", !ziele.length);
  h.textContent = ziele.length ? `🔘 Wird nach dem Senden als Knopf angezeigt: ${ziele.map((z) => `„${z.sym} ${z.t}“`).join(", ")}` : "";
}
function entwurfWeg(id) { const d = entwurfAlle(); if (!(id in d)) return; delete d[id]; try { localStorage.setItem(entwurfSchluessel(), JSON.stringify(d)); } catch {} }
// ---------- KC-CLUB-NACH-UNTEN (1.12.0): ⬇️ nur, wenn man weit nach oben gescrollt hat ----------
const weitOben = () => document.documentElement.scrollHeight - (window.scrollY + window.innerHeight) > 500;
function nachUntenPruefen() {
  const k = $("nachUnten"); if (!k) return;
  const zeigen = aktuelleAnsicht === "chat" && weitOben();
  if (!zeigen && !weitOben()) NA.neuUnten = false;
  k.classList.toggle("versteckt", !zeigen);
  k.innerHTML = "⬇️" + (NA.neuUnten ? '<span class="punkt-neu" title="Neue Nachricht"></span>' : "");
}
function nachUntenSpringen() { NA.neuUnten = false; window.scrollTo({ top: document.documentElement.scrollHeight, behavior: "smooth" }); setTimeout(nachUntenPruefen, 600); }
window.addEventListener("scroll", () => { if (aktuelleAnsicht === "chat") nachUntenPruefen(); }, { passive: true });
function tippenAus() { clearTimeout(TIPP.nach); if (TIPP.id) api("tippen", { id: TIPP.id, aus: true }).catch(() => {}); TIPP = { zuletzt: 0, id: null, nach: null }; }
async function liveTippenSetzen(an) {
  try { await api("einstellung_setzen", { schluessel: "live_tippen", wert: { an } }); if (INIT?.einstellungen) INIT.einstellungen.live_tippen = { an };
    melde(an ? "👁️ Live-Tippen an – andere sehen in Unterhaltungen, was du tippst" : "Live-Tippen aus – andere sehen nur noch „schreibt …“"); }
  catch (e) { meldeFehler(e); if ($("setLiveTippen")) $("setLiveTippen").checked = !an; }
}
const OSZI_SVG = `<svg class="oszi" viewBox="0 0 70 24" aria-hidden="true"><g class="hub"><g class="lauf"><path d="M0 12 ${Array.from({ length: 10 }, (_, i) => `Q${i * 10 + 5} ${i % 2 ? 22 : 2} ${i * 10 + 10} 12`).join(" ")}"/></g></g></svg>`;
const werText = (n) => n.length === 1 ? n[0] : n.length === 2 ? `${n[0]} und ${n[1]}` : `${n.length} Personen`;
function tipptZeigen(namen, entwurf = [], sprechen = []) {
  const e = $("tipptAnzeige"); if (!e) return;
  if (!namen.length && !sprechen.length) { e.classList.add("versteckt"); e.innerHTML = ""; e.dataset.stand = ""; return; }
  // KC-CLUB-SPRICHT (1.11.0): „nimmt eine Sprachnachricht auf“ mit Oszilloskop-Welle
  const sp = sprechen.length ? `<div class="zeile">${OSZI_SVG}<span>🎤 ${esc(werText(sprechen))} ${sprechen.length > 1 ? "nehmen" : "nimmt"} eine Sprachnachricht auf</span></div>` : "";
  if (!namen.length) { if (e.dataset.stand !== sp) { e.innerHTML = sp; e.dataset.stand = sp; } e.classList.remove("versteckt"); return; }
  const kurz = (t) => { const z = [...t]; return z.length > LIVE_ANZEIGE_ZEICHEN ? "…" + z.slice(-LIVE_ANZEIGE_ZEICHEN).join("") : t; };
  const entwuerfe = entwurf.map((x) => `<div class="entwurf">✍️ <b>${esc(x.name)}:</b> ${esc(kurz(x.text))}</div>`).join("");
  const wer = namen.length === 1 ? namen[0] : namen.length === 2 ? `${namen[0]} und ${namen[1]}` : `${namen.length} Personen`;
  // 1.21.5: nur neu zeichnen, wenn sich etwas geändert hat – sonst fängt die Punkte-Welle bei jedem Takt (2 s) von vorn an
  const html = `<div class="zeile"><span class="punkte3"><i></i><i></i><i></i></span><span>✏️ ${esc(wer)} ${namen.length > 1 ? "schreiben" : "schreibt"} …</span></div>${entwuerfe}${sp}`;
  if (e.dataset.stand !== html) { e.innerHTML = html; e.dataset.stand = html; }
  e.classList.remove("versteckt");
}

// ---------- KC-CLUB-ANRUF (0.31.0, Test): Sprechen per Ton, direkt App zu App (WebRTC) ----------
// Aufbau: Anrufer schickt sein „Angebot“ (SDP) über unseren Server, der Angerufene seine „Antwort“; danach läuft die Sprache
// direkt zwischen den Handys. Kostenlose öffentliche STUN-Server helfen, den Weg durchs Heimnetz zu finden. Klappt das nicht
// (manche Mobilfunknetze), sagt die App es ehrlich und bietet Nachricht/Anruf übers Telefon an.
const ICE = [{ urls: ["stun:stun.l.google.com:19302", "stun:stun1.l.google.com:19302"] }];
let RUF = null; // { id, pc, strom, rolle, poll, uhr, start, gegen, verbunden, klang }
function iceFertig(pc, ms = 3500) {
  return new Promise((ok) => { if (pc.iceGatheringState === "complete") return ok(); const t = setTimeout(ok, ms);
    pc.addEventListener("icegatheringstatechange", () => { if (pc.iceGatheringState === "complete") { clearTimeout(t); ok(); } }); });
}
async function anrufVerbindung(mitBild) {
  if (!navigator.mediaDevices?.getUserMedia || !window.RTCPeerConnection) throw new Error("Dieses Handy/dieser Browser kann keine App-Anrufe.");
  let strom;
  try { strom = await navigator.mediaDevices.getUserMedia({ audio: { echoCancellation: true, noiseSuppression: true },
    video: mitBild ? { facingMode: "user", width: { ideal: 640 }, height: { ideal: 480 } } : false }); }
  catch { throw new Error(mitBild ? "Bitte Kamera und Mikrofon erlauben (Chrome fragt danach) – sonst geht der Videoanruf nicht." : "Bitte das Mikrofon erlauben (Chrome fragt danach) – sonst geht der Anruf nicht."); }
  const pc = new RTCPeerConnection({ iceServers: ICE });
  strom.getTracks().forEach((t) => pc.addTrack(t, strom));
  // KC-CLUB-VIDEO: wer „nur mit Ton“ annimmt, empfängt das Bild trotzdem (der Video-Kanal kommt aus dem Angebot)
  if (mitBild) { $("anrufSelbst").srcObject = strom; $("anrufSelbst").classList.remove("versteckt"); }
  pc.ontrack = (e) => {
    $("anrufTon").srcObject = e.streams[0]; $("anrufTon").play?.().catch(() => {});
    if (e.track.kind === "video") { $("anrufVideo").srcObject = e.streams[0]; $("anrufVideo").classList.remove("versteckt"); $("anrufSchirm").classList.add("mitbild"); }
  };
  pc.onconnectionstatechange = () => {
    if (!RUF || RUF.pc !== pc) return;
    if (pc.connectionState === "connected" && !RUF.verbunden) { RUF.verbunden = true; RUF.start = Date.now(); klangAus(); anrufUhr(); anrufKnoepfe("aktiv"); if (RUF.vf) { melde(`🔊 Ton an – ihr könnt jetzt miteinander sprechen`); vfLeiste(); } }
    if (pc.connectionState === "connected" && RUF.konf) { const h = RUF.konf.beine.get(RUF.id); if (h) h.verbunden = true; konfAnzeigen(); } // KC-CLUB-KONFERENZ: Hauptverbindung steht
    if (pc.connectionState === "failed") { if (RUF.konf) konfBeinWeg(RUF.id, true); else anrufFehlgeschlagen(); }
    if (pc.connectionState === "disconnected" && !RUF.konf) anrufZustand("⚠️ Verbindung wackelt …");
  };
  return { pc, strom };
}
// kleiner Klingel-/Freiton über die Lautsprecher (ohne Audiodatei); Vibration dazu
function klang(art) {
  klangAus();
  try {
    const ctx = new (window.AudioContext || window.webkitAudioContext)(), an = [];
    const ton = () => { const o = ctx.createOscillator(), g = ctx.createGain(); o.frequency.value = art === "klingeln" ? 880 : 425; g.gain.value = art === "klingeln" ? 0.18 : 0.08;
      o.connect(g).connect(ctx.destination); o.start(); o.stop(ctx.currentTime + (art === "klingeln" ? 0.35 : 1)); an.push(o); };
    ton(); const t = setInterval(() => { ton(); if (art === "klingeln") { setTimeout(ton, 450); try { navigator.vibrate?.([300, 150, 300]); } catch {} } }, art === "klingeln" ? 1800 : 4000);
    RUF && (RUF.klang = { ctx, t });
  } catch {}
}
