// ➕ während eines Gesprächs jemanden anrufen und dazuholen
function konfDrin() { const K = RUF?.konf; return new Set([ICH.person_id, RUF?.gegen?.person_id, ...(K?.teilnehmer || []).map((t) => t.person_id), ...(K?.eingeladen || []).map((t) => t.person_id), ...[...(K?.beine.values() || [])].map((b) => b.gegen?.person_id)].filter(Boolean)); }
