// ---- KC-CLUB-HEARTBEAT (0.84.0): Lebenszeichen wie die anderen KC-Programme. Die App meldet alle 60 s über ihren eigenen
// Server (Aktion „lebenszeichen“, angemeldet mit dem Club-Link – kein Schlüssel im Browser); der Server reicht es im
// KICC-Format an kicc-program-heartbeat weiter → kicc_program_heartbeats, sichtbar im KC System Check.
// Nur Technik: Programm, Gerät (Zufalls-ID), Version, Status – keine Namen oder Inhalte.
const HERZ = { takt: 60, abstand: 20, max: 15, lager: "kc_club_herz_v1", geraetLager: "kc-clubapp.instance.id.v1" };
let HB = null;
function herzGeraet() {
  try { let id = localStorage.getItem(HERZ.geraetLager); if (!id) { id = "browser-" + (crypto.randomUUID?.() || Math.random().toString(36).slice(2)); localStorage.setItem(HERZ.geraetLager, id); } return id; }
  catch { return "browser"; }
}
function herzListeLesen() { try { const l = JSON.parse(localStorage.getItem(HERZ.lager) || "[]"); return Array.isArray(l) ? l : []; } catch { return []; } }
function herzMerken(e) { const l = [...herzListeLesen(), e].slice(-HERZ.max); try { localStorage.setItem(HERZ.lager, JSON.stringify(l)); } catch {} }
function herzSchlag(ok) {
  const h = $("herzKnopf"); if (!h) return;
  h.classList.toggle("fehlt", !ok); h.classList.remove("schlag"); void h.offsetWidth; if (ok) h.classList.add("schlag");
  const l = herzListeLesen().slice(-1)[0]; // 2.17.3: .at() gibt es in älteren Browsern nicht
  h.title = l ? `Lebenszeichen ${l.ok ? "ok" : "fehlt – " + l.grund} · ${new Date(l.zeit).toLocaleTimeString("de-DE")} · antippen: die letzten 15` : "Lebenszeichen – noch keins gesendet";
}
async function herzSenden() {
  if (!KEY || !ICH) return;
  // KC-CLUB-HERZ-ABSTAND (0.88.0): Zurück in die App + Minutentakt konnten zwei Lebenszeichen binnen 2 s schicken – der
  // Empfänger nimmt je Gerät höchstens eins pro 5 s an („rate_limited“, rot in der Liste, obwohl alles lief). Mindestabstand 20 s.
  const jetzt = Date.now(); if (herzSenden.laeuft || jetzt - (herzSenden.zuletzt || 0) < HERZ.abstand * 1000) return;
  herzSenden.laeuft = true; herzSenden.zuletzt = jetzt;
  const t0 = performance.now();
  try {
    const r = await apiRoh("lebenszeichen", { geraet: herzGeraet(), sichtbar: document.visibilityState !== "hidden", verkehr: verkehrStand() });
    const ms = Math.round(performance.now() - t0);
    herzMerken({ zeit: new Date().toISOString(), ok: !!r.ok, ms, grund: r.ok ? "" : String(r.grund || "nicht angenommen").slice(0, 60) }); herzSchlag(!!r.ok);
  } catch (e) { herzMerken({ zeit: new Date().toISOString(), ok: false, ms: Math.round(performance.now() - t0), grund: String(e.message || e).slice(0, 60) }); herzSchlag(false); }
  finally { herzSenden.laeuft = false; }
  // ein fehlendes Lebenszeichen darf die App nie stören – kein Fehlerfenster, nur das blasse Herz
}
function herzStarten() {
  if (HB) return;
  HB = setInterval(() => { if (document.visibilityState !== "hidden") herzSenden(); }, HERZ.takt * 1000);
  setTimeout(herzSenden, 5000);
  document.addEventListener("visibilitychange", () => { if (!document.hidden) herzSenden(); });
}
function herzListe() {
  const l = herzListeLesen();
  const heute = new Date().toDateString(), zeitText = (z) => { const d = new Date(z); return (d.toDateString() === heute ? "" : d.toLocaleDateString("de-DE", { day: "2-digit", month: "2-digit" }) + " ") + d.toLocaleTimeString("de-DE"); };
  const zeile = (e) => `<tr><td style="white-space:nowrap">${esc(zeitText(e.zeit))}</td>
    <td class="${e.ok ? "ok" : "weg"}">${e.ok ? "● angekommen" : "● fehlt – " + esc(e.grund || "")}</td><td>${Number.isFinite(e.ms) ? e.ms + " ms" : ""}</td></tr>`;
  $("herzText").innerHTML = `<h3 style="margin-top:0">♥ Lebenszeichen – die letzten ${HERZ.max}</h3>
    <p class="hinweis" style="margin-top:0">Jede Minute meldet die App dem KC System Check „ich laufe“ und wie viele Datenabrufe sie bisher gemacht hat – nur Technik, keine Namen oder Inhalte. Das Herz blinkt bei jedem Lebenszeichen kurz rot.</p>`
    + (l.length ? `<table class="herz-tabelle"><tr><th>Zeit</th><th>Stand</th><th>Antwort</th></tr>${[...l].reverse().map(zeile).join("")}</table>` : '<p class="hinweis">Noch kein Lebenszeichen gesendet – das erste kommt wenige Sekunden nach dem Start.</p>')
    + `<p class="hinweis" style="margin:8px 0 0">Programm: kc-clubapp · Gerät: ${esc(herzGeraet().slice(0, 16))} · Version ${esc(APP_VERSION)}</p>`;
  $("herzBlatt").classList.remove("versteckt");
}
// ---- KC-CLUB-ANRUF-VERPASST (0.81.0): „Verpasster Anruf“ mit Zurückrufen ----
let VERPASST = [];
