  if (n.i >= n.e.zuege.length) n.i = 0;
  n.takt = setInterval(() => { if (SCH_NS !== n || aktuelleAnsicht !== "spiele") return clearInterval(n.takt); schNsGehe(n.i + 1); }, 1400);
  schNsGehe(n.i + 1);
