  if (a === "ja") return spStart();
  if (a === "spaeter") { clearTimeout(spEinlAntwort.t); spEinlAntwort.t = setTimeout(() => spEinladung(), SPE_SPAETER_MS + 1000); return melde("⏰ Gut, ich frage ein andermal"); }
