const spTitel = (g) => g.spiel === "schach" ? "♟️ Schach" : g.spiel === "bsk" ? "🃏 Bauernskat" : g.spiel === "kt" ? "🔪 Küchenterror" : g.spiel === "mae" ? "🎲 Mensch ärgere dich nicht" : `❌⭕ Tic-Tac-Toe ${g.groesse}×${g.groesse}`;
