function zeitSignal(ms) { if (AbortSignal.timeout) return AbortSignal.timeout(ms); const c = new AbortController(); setTimeout(() => c.abort(), ms); return c.signal; }
const VERKEHR_LAGER = "kc_club_verkehr_v1";
// KC-CLUB-DATENSTROM (0.89.0): echter Zähler der Datenabrufe dieses Geräts (jede beantwortete Anfrage an den Club-Server,
// das Lebenszeichen selbst zählt nicht). Er steigt nur und reist mit dem Lebenszeichen als trafficTx mit; der KC System Check
// zeigt auf der Linie „KC Club-App → Supabase“ nur dann Bewegung, wenn der Zähler zwischen zwei Lebenszeichen gestiegen ist.
function verkehrStand() { try { const n = Number(localStorage.getItem(VERKEHR_LAGER)); return Number.isSafeInteger(n) && n >= 0 ? n : 0; } catch { return 0; } }
function verkehrZaehlen() { try { localStorage.setItem(VERKEHR_LAGER, String(verkehrStand() + 1)); } catch {} }
// KC-CLUB-NAHE-REGION (1.16.0): Server-Code im selben Rechenzentrum wie die Datenbank ausführen (Supabase „Regional Invocation“,
// kostenlos) – sonst läuft er beim Mitglied (Frankfurt) und jede Datenbank-Abfrage geht nach London und zurück.
// Beim Umzug der Datenbank SERVER_REGION mitändern. Rückweg: Antwortet die Region nicht, sofort ohne Region (Standard) und
// für REGION_PAUSE_MS dabei bleiben – die App hängt nie an einer einzelnen Region (Regel 12).
