// Notfall: Spiegel sofort anstoßen (verbraucht Neon-Rechenzeit – daher mit Rückfrage)
async function adminSpiegeln() {
  if (!(await frage("Spiegel Supabase → Neon jetzt sofort anstoßen?\n\nDas verbraucht Neon-Rechenzeit – bitte nur im Notfall. Normal läuft er alle 6 Stunden von selbst."))) return;
  try { const r = await api("admin_spiegeln"); const e = r.ergebnis || {};
    melde(e.status === "mirror_dispatched" ? `🪞 Spiegel angestoßen (${e.tables} Tabellen)` : e.status === "maintenance" ? "Neon ist gerade in Wartung – nichts gestartet." : "Nichts zu spiegeln.");
    if (INFO_DATEN.admin) INFO_DATEN.admin.geholt = 0;
  } catch (e) { meldeFehler(e); }
}
