  const tage = d.tage.slice(0, WETTER_TAGE_LEISTE).map((t, i) => `<button class="wtag${i === WET.tag ? " an" : ""}" onpointerdown="wtDruck(event, ${i})" onpointermove="wtBewegt(event)" onpointerup="wtLos(${i})" onpointercancel="wtLos(${i}, true)" onpointerleave="wtLos(${i}, true)" oncontextmenu="return false" aria-label="${esc(wetterTagName(i, t.datum))}: ${esc(wetterArt(t.code).text)}">
      <span>${esc(wetterTagKurz(i, t.datum))}${t.datum === treffenTag ? " 📅" : ""}</span><b>${wetterArt(t.code).sym}</b><span>${grad(t.max)} / ${grad(t.min)}</span>${t.regenWkt != null ? `<small>☔ ${t.regenWkt} %</small>` : ""}</button>`).join("");
