    zeile2 = `📍 ${esc(r.ort.name)} · gefühlt ${grad(j.gefuehlt)} · 💨 ${Math.round(j.wind)} km/h${j.boeen >= WIND_HINWEIS_KMH ? ` (Böen ${Math.round(j.boeen)})` : ""}`;
    szene = `szene-${a.szene}${j.boeen >= STURM_KMH ? " sturm" : ""}${j.tag ? "" : " nacht"}`;
