    zeile2 = `📍 ${esc(r.ort.name)}${t.regenWkt != null ? ` · ☔ ${t.regenWkt} %` : ""}${t.regenMm ? ` (${String(t.regenMm).replace(".", ",")} mm)` : ""}${t.windMax != null ? ` · 💨 bis ${Math.round(t.windMax)} km/h` : ""} <button class="wlink wzurueck" onclick="wetterTagWahl(0)">↩ jetzt</button>`;
