const fbKarte = (z) => `<span class="fb-z" data-z="${esc(z)}"><span class="fb-h fb-oben"><i>${esc(z.trim())}</i></span><span class="fb-h fb-unten"><i>${esc(z.trim())}</i></span></span>`;
