new MutationObserver(() => { if (blattXPlan || !document.querySelector(".blatt:not(.versteckt)")) return; blattXPlan = requestAnimationFrame(() => { blattXPlan = 0; try { blattXPruefen(); } catch {} try { blattHakenPruefen(); } catch {} }); })
