// ---------- Geburtstage: Liste der nächsten Tage + eigene Freigabe ----------
function geburtstageListe(geb, tage) {
  const heute = heuteIso(), n = [];
  for (let i = 0; i < tage; i++) {
    const tag = tagPlus(heute, i), md = tag.slice(5), schalt = new Date(Date.UTC(+tag.slice(0, 4), 1, 29)).getUTCDate() === 29;
    for (const g of geb) if (g.md === md || (!schalt && md === "02-28" && g.md === "02-29")) n.push({ tag, g });
  }
  if (!n.length) return "";
  return `<div class="karte"><h3>🎂 Geburtstage in den nächsten ${tage} Tagen</h3>${n.map(({ tag, g }) => {
    const ich = g.person_id === ICH?.person_id, wann2 = tag === heute ? "heute" : tag === tagPlus(heute, 1) ? "morgen" : fTagDp.format(new Date(tag + "T12:00:00Z"));
    return `<div class="keintrag"${ich ? "" : ` onclick="gratulieren('${g.person_id}', true)"`}><div class="farbe" style="background:var(--lila)"></div><div style="flex:1"><b>${esc(ich ? "Du" : g.name)}</b><small>${esc(wann2)}${!ich && tag === heute ? " · 💬 antippen zum Gratulieren" : ""}</small></div>${ich ? "🎉" : '<b style="color:var(--rot)">›</b>'}</div>`;
  }).join("")}</div>`;
}
