// KC-CLUB-SI-MUETZE (1.19.0): Mütze mit fortgesetzter Phase (negative Verzögerung = „läuft schon so lange“) – kein Neustart beim Neuzeichnen
const siMuetze = (klasse = "", label = "") => { const t = performance.now() / 1000;
  return `<span class="si-muetze ${klasse}" style="--si1:-${(t % 5).toFixed(2)}s;--si2:-${(t % 14).toFixed(2)}s"${label ? ` role="img" aria-label="${label}"` : ' aria-hidden="true"'}><span><img src="kc-kochmuetze-weiss.webp" alt=""></span></span>`; };
// ---------- KC-CLUB-SICHERHEIT (1.14.0, Wunsch Hansi): Sicherheits-Check – zeigt Mitgliedern, dass alles läuft und geschützt ist ----------
// Jede Zeile ist eine echte Prüfung (App oder Server). Keine Namen von Datenbanken/Anbietern. Regel 11: Was sich nicht prüfen
// lässt, steht als „nicht geprüft“ da – nie als OK. „Alle Systeme laufen einwandfrei“ nur, wenn wirklich jede Zeile OK ist.
// Registry SICHERHEIT_PRUEFUNGEN: neue Prüfung = neuer Eintrag (wert(r) liefert true/false/null, info(r) den Zusatztext).
const siZeit = (min) => min == null ? "" : min < 60 ? `vor ${Math.max(1, Math.round(min))} Min.` : min < 48 * 60 ? `vor ${Math.round(min / 60)} Std.` : `vor ${Math.round(min / 1440)} Tagen`;
const SICHERHEIT_PRUEFUNGEN = [
  { id: "verbindung", sym: "🔐", t: "Verbindung verschlüsselt", wert: () => location.protocol === "https:", info: () => location.protocol === "https:" ? "Alles, was du sendest, ist auf dem Weg geschützt" : "Seite nicht über eine geschützte Verbindung geöffnet" },
  { id: "zugang", sym: "🔑", t: "Dein persönlicher Zugang ist gültig", wert: (r) => r.zugang, info: (r) => r.zugang ? "Nur mit deinem eigenen Link" : "" },
  { id: "server", sym: "🛰️", t: "Server erreichbar", wert: (r) => r.serverMs != null, info: (r) => r.serverMs != null ? `Antwort in ${r.serverMs} ms` : "" },
  { id: "datenbank", sym: "🗄️", t: "Daten-Speicher antwortet", wert: (r) => r.s ? r.s.dbMs != null : null, info: (r) => r.s?.dbMs != null ? `Antwort in ${r.s.dbMs} ms` : "" },
  { id: "verschluesselt", sym: "🔒", t: "Daten verschlüsselt gespeichert", fest: true, wert: (r) => r.s ? r.s.dbMs != null : null, info: () => "Fest eingebaut – lässt sich nicht abschalten" },
  { id: "schutz", sym: "🧱", t: "Zugriffsschutz auf allen Daten", wert: (r) => r.s?.schutz ?? null, info: () => "Jeder sieht nur, was er sehen darf" },
  { id: "spiegel", sym: "🪞", t: "Sicherungskopie in zweitem Speicher aktuell", wert: (r) => r.s?.spiegel ?? null, info: (r) => r.s?.spiegelMin != null ? `Abgeglichen ${siZeit(r.s.spiegelMin)}` : "" },
  { id: "sicherung", sym: "💾", t: "Nächtliche Datensicherung", wert: (r) => r.s?.sicherung ?? null, info: (r) => r.s?.sicherungAm ? `Zuletzt ${new Date(r.s.sicherungAm).toLocaleString("de-DE", { weekday: "short", hour: "2-digit", minute: "2-digit" })} Uhr` : "" },
  { id: "wiederherstellung", sym: "♻️", t: "Wiederherstellung erfolgreich getestet", wert: (r) => r.s?.wiederherstellung ?? null, info: () => "Die Sicherung wird regelmäßig zur Probe zurückgespielt" },
  { id: "ueberwachung", sym: "👁️", t: "Überwachung rund um die Uhr aktiv", wert: (r) => r.s?.ueberwachung ?? null, info: (r) => r.s?.ueberwachungMin != null ? `Letzte Kontrolle ${siZeit(r.s.ueberwachungMin)}` : "" },
  { id: "version", sym: "🔄", t: "App auf dem neuesten Stand", wert: (r) => r.neueste == null ? null : r.neueste === APP_VERSION, info: (r) => r.neueste && r.neueste !== APP_VERSION ? `Neu: v${r.neueste} – unter Technik → Update` : `v${APP_VERSION}` },
];
// Rundinstrumente: Grenzen je Messung (ms) – schnell / normal / langsam, immer mit Wort (nicht nur Farbe)
const SI_UHREN = [
  { id: "server", t: "App ↔ Server", max: 2500, gut: 1000, mittel: 2000, wert: (r) => r.serverMs }, // 2.23.73 (Wunsch Hansi): Handy-Netz realistisch – bis 1 s grün
  { id: "datenbank", t: "Daten-Speicher", max: 1000, gut: 300, mittel: 700, wert: (r) => r.s?.dbMs ?? null },
];
let SI = { laeuft: false, r: null, zeit: null };
function sicherheitStart() { zeige("sicherheit"); if (!SI.laeuft) sicherheitPruefen(); }
function siKlasse(ok) { return ok === true ? "si-gut" : ok === false ? "si-schlecht" : "si-offen"; }
function siUhr(u, r) {
  const v = r ? u.wert(r) : null, anteil = v == null ? 0 : Math.min(1, v / u.max), laenge = Math.PI * 50;
  const kl = v == null ? "si-offen" : v <= u.gut ? "si-gut" : v <= u.mittel ? "si-mittel" : "si-schlecht";
  const wort = v == null ? (r ? "nicht gemessen" : "…") : v <= u.gut ? "✓ schnell" : v <= u.mittel ? "◐ normal" : "⚠ langsam";
  return `<div class="karte si-uhr ${kl}" role="img" aria-label="${esc(u.t)}: ${v == null ? "nicht gemessen" : v + " Millisekunden, " + wort.replace(/^\S+ /, "")}">
    <svg viewBox="0 0 120 68" aria-hidden="true"><path class="spur" d="M10 60 A50 50 0 0 1 110 60"/><path class="wert" d="M10 60 A50 50 0 0 1 110 60" stroke-dasharray="${laenge}" stroke-dashoffset="${laenge * (1 - anteil)}"/></svg>
    <div class="zahl">${v == null ? "–" : v}<small> ms</small></div><div class="wort">${wort}</div><div class="titel">${esc(u.t)}</div></div>`;
}
function sicherheitZeigen(schritt) {
  const r = SI.r, n = SICHERHEIT_PRUEFUNGEN.length, fertig = r && schritt >= n;
  const werte = SICHERHEIT_PRUEFUNGEN.map((p) => (r ? p.wert(r) : null));
  const schlecht = werte.filter((w) => w === false).length, offen = werte.filter((w) => w == null).length;
  const kopf = !fertig
    ? `<div class="si-ergebnis si-offen">${siMuetze("", "Prüfung läuft")}<div><b>Prüfung läuft …</b><span class="hinweis">${Math.min(schritt ?? 0, n)} von ${n} Punkten geprüft</span></div></div>`
    : !schlecht && !offen
      ? `<div class="si-ergebnis si-gut"><span class="gross">✅</span><div><b>Alle Systeme laufen einwandfrei</b><span class="hinweis">Deine Daten sind geschützt und gesichert · geprüft ${esc(SI.zeit)} Uhr</span></div></div>`
      : `<div class="si-ergebnis ${schlecht ? "si-schlecht" : "si-mittel"}"><span class="gross">⚠️</span><div><b>${schlecht + offen} ${schlecht + offen === 1 ? "Punkt ist" : "Punkte sind"} gerade nicht bestätigt</b><span class="hinweis">Bitte in ein paar Minuten noch einmal prüfen. Bleibt es so, gib ${adminName()} kurz Bescheid. · ${esc(SI.zeit || "")} Uhr</span></div></div>`;
  // KC-CLUB-SI-MUETZE (1.19.0, Hinweis Hansi „obere Mütze ruckelt“): nicht mehr alles neu zeichnen – Kopf, Uhren, Liste und Knöpfe
  // sind eigene Bereiche; während der Prüfung ändert sich nur der Zähler und die Zeilen, die fertig geworden sind. Die laufenden
  // Mützen bleiben unangetastet und drehen ungestört weiter.
  const zeilen = SICHERHEIT_PRUEFUNGEN.map((p, i) => {
    const sichtbar = r && i < (schritt ?? 0), w = werte[i], info = sichtbar ? p.info(r) : "";
    const st = !sichtbar ? `<span class="st si-offen">${siMuetze("klein")}</span>` : `<span class="st ${siKlasse(w)}">${w === true ? (p.fest ? "immer an" : "OK") : w === false ? "Achtung" : "nicht geprüft"}</span>`;
    return { key: sichtbar ? `${w}|${info}` : "laeuft", html: `<li><span class="sym">${p.sym}</span><span>${esc(p.t)}${info ? `<small>${esc(info)}</small>` : ""}</span>${st}</li>` };
  });
  if (!$("siKopf")) $("siInhalt").innerHTML = '<div id="siKopf"></div><div class="si-uhren" id="siUhren"></div><div class="karte"><ul class="si-liste" id="siListe"></ul></div><div id="siKnoepfe"></div>';
  const kopfKey = fertig ? `fertig|${schlecht}|${offen}|${SI.zeit}` : "laeuft";
  if ($("siKopf").dataset.key !== kopfKey) { $("siKopf").innerHTML = kopf; $("siKopf").dataset.key = kopfKey; }
  else if (!fertig) { const z = $("siKopf").querySelector(".hinweis"); if (z) z.textContent = `${Math.min(schritt ?? 0, n)} von ${n} Punkten geprüft`; }
  $("siUhren").innerHTML = SI_UHREN.map((u) => siUhr(u, fertig ? r : null)).join("");
  const lis = $("siListe").children;
  if (lis.length !== zeilen.length) { $("siListe").innerHTML = zeilen.map((z) => z.html).join(""); [...$("siListe").children].forEach((li, i) => (li.dataset.key = zeilen[i].key)); }
  else zeilen.forEach((z, i) => { if (lis[i].dataset.key !== z.key) { lis[i].outerHTML = z.html; $("siListe").children[i].dataset.key = z.key; } });
  $("siKnoepfe").innerHTML = `<button class="knopf ${fertig && (schlecht || offen) ? "" : "haupt"}" style="margin-top:12px" ${SI.laeuft ? "disabled" : ""} onclick="sicherheitPruefen()">🔍 ${SI.r ? "Erneut prüfen" : "Jetzt prüfen"}</button>
    ${fertig ? `<button class="knopf ${schlecht || offen ? "haupt" : ""}" style="margin-top:8px" onclick="sicherheitMelden()">📨 Ergebnis an ${adminName()} (Admin) senden</button>` : ""}
    <p class="hinweis" style="margin-top:8px">Die Prüfung schaut nur nach – sie verändert nichts und verrät keine Daten.</p>`;
}
async function sicherheitPruefen() {
  if (SI.laeuft) return;
  SI = { laeuft: true, r: null, zeit: null }; sicherheitZeigen(0);
  const r = { zugang: null, serverMs: null, s: null, neueste: null };
  const t0 = performance.now();
  // zwei Messungen, der bessere Wert zählt – das erste Aufwecken des Servers soll die Anzeige nicht verfälschen
  try { r.s = await api("sicherheit_pruefen", {}, { warten: false }); r.serverMs = Math.round(performance.now() - t0); r.zugang = true;
    const t1 = performance.now(), s2 = await api("sicherheit_pruefen", {}, { warten: false }).catch(() => null), ms2 = Math.round(performance.now() - t1);
    if (s2 && ms2 < r.serverMs) { r.serverMs = ms2; r.s = { ...s2, dbMs: Math.min(s2.dbMs ?? Infinity, r.s.dbMs ?? Infinity) }; } else if (s2?.dbMs != null && r.s.dbMs != null) r.s.dbMs = Math.min(r.s.dbMs, s2.dbMs); }
  catch (e) { r.zugang = /zugang|link|berechtig/i.test(e.message) ? false : null; }
  try { r.neueste = (await (await fetch("version.json?t=" + Date.now(), { cache: "no-store", signal: zeitSignal(15000) })).json()).version || null; } catch {}
  SI.r = r; SI.zeit = new Date().toLocaleTimeString("de-DE", { hour: "2-digit", minute: "2-digit" });
  for (let i = 1; i <= SICHERHEIT_PRUEFUNGEN.length; i++) { if (aktuelleAnsicht !== "sicherheit") break; sicherheitZeigen(i); await new Promise((ok) => setTimeout(ok, 180)); }
  SI.laeuft = false; sicherheitZeigen(SICHERHEIT_PRUEFUNGEN.length);
  const alleOk = SICHERHEIT_PRUEFUNGEN.every((p) => p.wert(r) === true);
  try { navigator.vibrate?.(alleOk ? 40 : [60, 60, 60]); } catch {}
}

// KC-CLUB-SICHERHEIT-MELDEN (1.15.0): Ergebnis an die Admins – der Server prüft dabei selbst neu
async function sicherheitMelden() {
  const r = SI.r; if (!r) return;
  const schlecht = SICHERHEIT_PRUEFUNGEN.some((p) => p.wert(r) !== true);
  const notiz = schlecht ? (await eingabe("Möchtest du kurz etwas dazuschreiben? (freiwillig)", "")) : "";
  if (notiz === null) return;
  try {
    await api("sicherheit_melden", { notiz, geraet: { verbindung: location.protocol === "https:", version: r.neueste == null ? null : r.neueste === APP_VERSION, serverMs: r.serverMs } }, { warten: true });
    melde("📨 Gesendet – " + adminName() + " bekommt das Prüfergebnis per Push und E-Mail");
  } catch (e) { meldeFehler(e); }
}
// ---------- KC-CLUB-BEARBEITEN (1.9.0, Wunsch Hansi – wie WhatsApp): eigene Nachricht bis 15 Min. nach dem Senden ändern ----------
function naBearbeiten(id) {
  const m = NA.nachrichten.get(id); if (!m) return;
  document.getElementById("naMenue")?.remove();
  const f = document.createElement("div"); f.id = "naMenue"; f.className = "blatt"; f.setAttribute("role", "dialog"); f.setAttribute("aria-modal", "true");
  const rest = Math.max(1, Math.round((Date.parse(m.bearbeitbarBis) - Date.now()) / 60000));
  f.innerHTML = `<div class="blatt-innen na-menue"><h3 style="margin:0">✏️ Nachricht bearbeiten</h3>
    <textarea id="naBearbText" spellcheck="true" lang="de" autocapitalize="sentences" autocorrect="on" maxlength="4000" style="width:100%;min-height:110px;box-sizing:border-box;padding:10px;border-radius:12px;border:1px solid var(--linie);font:inherit;background:var(--karte);color:inherit"></textarea>
    <p class="hinweis" style="margin:0">Noch ${rest} Min. möglich. Die anderen sehen danach „bearbeitet“ – es kommt keine neue Benachrichtigung.</p>
    <button class="knopf haupt" onclick="naBearbeitenSpeichern('${id}')">💾 Speichern</button>
    <button class="knopf" onclick="document.getElementById('naMenue').remove()">Abbrechen</button></div>`;
  f.onclick = (e) => { if (e.target === f) f.remove(); };
  document.body.appendChild(f);
  const ta = $("naBearbText"); ta.value = m.text || ""; ta.focus(); ta.setSelectionRange(ta.value.length, ta.value.length);
}
async function naBearbeitenSpeichern(id) {
  const text = $("naBearbText")?.value.trim() || "";
  if (!text) return melde("Bitte einen Text eingeben – zum Entfernen „Löschen“ benutzen.", true);
  try { await api("nachricht_bearbeiten", { id, text }); document.getElementById("naMenue")?.remove(); melde("✏️ Geändert"); chatStand = ""; await chatLaden(false); }
  catch (e) { meldeFehler(e); }
}

// ---------- KC-CLUB-STUMM (1.9.0, Wunsch Hansi): einzelne Unterhaltungen stummschalten – kein Push, keine Mail, kein Ton ----------
// @Erwähnungen kommen trotzdem (wie WhatsApp). Einstellung „stumm“ geräteübergreifend; Dauer-Registry STUMM_DAUER.
const STUMM_DAUER = [{ id: "8h", t: "8 Stunden", ms: 8 * 3600000 }, { id: "1w", t: "1 Woche", ms: 7 * 86400000 }, { id: "immer", t: "Immer" }];
const stummStand = () => ({ threads: {}, ...(INIT?.einstellungen?.stumm || {}) });
function stummAn(id) { const b = stummStand().threads?.[id]; return !!id && (b === "immer" || (typeof b === "string" && Date.parse(b) > Date.now())); }
function stummBereichZeigen() {
  const el = $("chatStummBereich"); if (!el) return;
  if (!chatId) { el.innerHTML = ""; return; }
  const b = stummStand().threads[chatId];
  el.innerHTML = stummAn(chatId)
    ? `<button class="knopf haupt" onclick="stummSetzen(null)">🔔 Wieder laut schalten</button><p class="hinweis" style="margin:0 4px 6px;font-size:.85rem">🔕 Stumm ${b === "immer" ? "für immer" : "bis " + esc(new Date(b).toLocaleString("de-DE", { weekday: "short", day: "2-digit", month: "2-digit", hour: "2-digit", minute: "2-digit" })) + " Uhr"}. @Erwähnungen kommen trotzdem.</p>`
    : `<p style="margin:4px 4px 2px"><b>🔕 Stummschalten</b> <span class="hinweis" style="font-size:.85rem">– kein Push, keine Mail, kein Ton</span></p>
       <div class="stumm-wahl">${STUMM_DAUER.map((d) => `<button class="knopf" onclick="stummSetzen('${d.id}')">${esc(d.t)}</button>`).join("")}</div>`;
}
async function stummSetzen(dauer) {
  if (!chatId) return;
  const threads = { ...stummStand().threads }, d = STUMM_DAUER.find((x) => x.id === dauer);
  if (!d) delete threads[chatId]; else threads[chatId] = d.id === "immer" ? "immer" : new Date(Date.now() + d.ms).toISOString();
  const w = { threads };
  if (INIT) INIT.einstellungen = { ...(INIT.einstellungen || {}), stumm: w };
  $("chatBlatt").classList.add("versteckt");
  try { await api("einstellung_setzen", { schluessel: "stumm", wert: w }); melde(d ? `🔕 Stumm – ${d.id === "immer" ? "für immer" : "für " + d.t}` : "🔔 Wieder laut"); }
  catch (e) { meldeFehler(e); }
  chatStand = ""; chatLaden(false);
}

// ---------- KC-CLUB-CHATSUCHE (1.9.0, Wunsch Hansi): Lupe im Chat – findet Wörter nur in diesem Gespräch ----------
// Sucht in den geladenen Nachrichten (Text + Absender), Umlaut-tolerant wie die große Suche; ▲▼ springt zwischen Treffern.
const CS = { offen: false, treffer: [], i: -1 };
function chatSucheAuf() { CS.offen = true; $("chatSuchLeiste").classList.remove("versteckt"); $("chatSuchFeld").focus(); chatSucheJetzt(true); }
function chatSucheZu() {
  CS.offen = false; CS.treffer = []; CS.i = -1; $("chatSuchFeld").value = ""; $("chatSuchLeiste").classList.add("versteckt");
  document.querySelectorAll("#chat .blase.su-treffer, #chat .blase.su-aktuell").forEach((b) => b.classList.remove("su-treffer", "su-aktuell"));
}
function chatSucheJetzt(neu) {
  const q = suNorm($("chatSuchFeld").value.trim()), alt = CS.treffer[CS.i];
  document.querySelectorAll("#chat .blase").forEach((b) => b.classList.remove("su-treffer", "su-aktuell"));
  CS.treffer = q.length < 2 ? [] : [...document.querySelectorAll("#chat .blase")].filter((b) => { const m = NA.nachrichten.get(b.dataset.id); return m && suNorm(`${m.text || ""} ${m.von || ""}`).includes(q); }).map((b) => b.dataset.id);
  CS.treffer.forEach((id) => document.querySelector(`.blase[data-id="${id}"]`)?.classList.add("su-treffer"));
  CS.i = neu ? CS.treffer.length - 1 : Math.max(0, CS.treffer.indexOf(alt)); // neu: beim neuesten Treffer anfangen
  $("chatSuchZahl").textContent = q.length < 2 ? "" : CS.treffer.length ? `${CS.i + 1} von ${CS.treffer.length}` : "keine Treffer";
  if (CS.treffer.length) chatSucheZeigen(neu);
}
function chatSucheSpringen(r) {
  if (!CS.treffer.length) return;
  CS.i = (CS.i + r + CS.treffer.length) % CS.treffer.length;
  $("chatSuchZahl").textContent = `${CS.i + 1} von ${CS.treffer.length}`;
  chatSucheZeigen(true);
}
function chatSucheZeigen(scrollen) {
  document.querySelectorAll("#chat .blase.su-aktuell").forEach((b) => b.classList.remove("su-aktuell"));
  const b = document.querySelector(`.blase[data-id="${CS.treffer[CS.i]}"]`); if (!b) return;
  b.classList.add("su-aktuell"); if (scrollen) b.scrollIntoView({ behavior: "smooth", block: "center" });
}

// KC-CLUB-NA-SEITE (1.8.3, Wunsch Hansi – wie WhatsApp): gebogener Pfeil neben der Nachricht → sofort weiterleiten oder kopieren
function naPfeilMenue(id) {
  const m = NA.nachrichten.get(id); if (!m) return;
  document.getElementById("naMenue")?.remove();
  const f = document.createElement("div"); f.id = "naMenue"; f.className = "blatt"; f.setAttribute("role", "dialog"); f.setAttribute("aria-modal", "true");
  // KC-CLUB-PFEIL-MENUE (2.23.80, Wunsch Hansi): am Pfeil einer einzelnen Nachricht zusätzlich ✂️ Ausschneiden (kopieren + löschen),
  // 🗄️ ins eigene Archiv legen und 🗑️ Löschen – schmale Knöpfe nebeneinander; Löschen/Ausschneiden fragen wie bisher nach (für mich / für alle)
  const zu = "document.getElementById('naMenue').remove();";
  f.innerHTML = `<div class="blatt-innen na-menue">
    <div class="na-vorschau">${m.eigen ? "Du" : esc(m.von)}: ${esc(String(m.text || "").slice(0, 120))}</div>
    <div class="na-pfeil-knoepfe">
      <button class="knopf haupt" onclick="${zu}weiterleitenBlatt('${id}')">↪️ Weiterleiten</button>
      ${m.text ? `<button class="knopf" onclick="${zu}naKopieren('${id}')">📋 Kopieren</button>` : ""}
      ${m.text ? `<button class="knopf" onclick="${zu}naAusschneiden('${id}')">✂️ Ausschneiden</button>` : ""}
      <button class="knopf" onclick="${zu}naInsArchiv('${id}')">🗄️ Archivieren</button>
      ${m.eigen || ICH?.admin ? `<button class="knopf" onclick="${zu}naWichtig('${id}', ${!m.wichtig})">${m.wichtig ? "➖ Nicht wichtig" : "❗ Wichtig"}</button>` : ""}
      <button class="knopf" onclick="${zu}naLoeschenFragen('${id}')">🗑️ Löschen</button>
      <button class="knopf" onclick="${zu}">Abbrechen</button></div></div>`;
  f.onclick = (e) => { if (e.target === f) f.remove(); };
  document.body.appendChild(f);
}
// ❗ Nachricht nachträglich als wichtig markieren (orangener Rahmen + „❗ WICHTIG“ wie beim Senden mit ❗) – eigene Nachricht oder Admin;
// alle im Chat sehen die Markierung, es geht KEINE neue Benachrichtigung raus
async function naWichtig(id, an) {
  try { await api("nachricht_wichtig", { id, an }); melde(an ? "❗ Als wichtig markiert – orange umrandet" : "Markierung „wichtig“ entfernt"); chatStand = ""; await chatLaden(false); }
  catch (e) { meldeFehler(e); }
}
// Ganzer Chat: Text kopieren (gleicher Verlaufstext wie fürs Archiv) und ausdrucken (Druck-Kern mit Vorschau)
async function chatKopieren() {
  if (!CHAT?.nachrichten?.length) return melde("In diesem Chat gibt es noch nichts zu kopieren.", true);
  const t = chatVerlaufText();
  try { await navigator.clipboard.writeText(t); return melde(`📋 Chat kopiert (${CHAT.nachrichten.length} Nachrichten)`); } catch {}
  await eingabe("Text markieren und kopieren:", t);
}
function druckChat() {
  const u = CHAT, msgs = u?.nachrichten || []; if (!msgs.length) return null;
  const zeilen = msgs.map((m) => { const wer = m.eigen ? ICH?.name || "Ich" : m.von, inhalt = m.umfrage ? `📊 Abstimmung: ${m.umfrage.frage || ""}` : m.kontakt ? `👤 Kontakt: ${m.kontakt.name || ""}` : m.text === "📎" ? "" : String(m.text || "");
    const dateien = (m.anlagen || []).map((a) => `📎 ${a.name}`).join(" · ");
    return `<tr${m.wichtig ? ' style="background:#fff3e0"' : ""}><td style="padding:1.2mm 2mm;border-bottom:.2mm solid #ccc;white-space:nowrap;vertical-align:top;font-size:3.1mm;color:#555">${esc(zeitDe(m.zeit))}</td>
      <td style="padding:1.2mm 2mm;border-bottom:.2mm solid #ccc;vertical-align:top;font-size:3.4mm"><b>${esc(wer)}</b>${m.wichtig ? " ❗" : ""}<br>${esc(inhalt).replace(/\n/g, "<br>")}${dateien ? `<br><span style="color:#555">${esc(dateien)}</span>` : ""}</td></tr>`; }).join("");
  return { titel: `Chat „${chatName()}“`, unter: `Teilnehmer: ${(u.teilnehmer || []).map((t) => t.name).join(", ")} · ${msgs.length} Nachricht${msgs.length === 1 ? "" : "en"}`,
    html: `<table style="width:100%;border-collapse:collapse">${zeilen}</table>`, fuss: "Chat-Ausdruck" };
}
// ✂️ Ausschneiden = Text kopieren, danach die gewohnte Lösch-Rückfrage (für mich / für alle – „Abbrechen“ lässt die Nachricht stehen)
async function naAusschneiden(id) { await naKopieren(id); naLoeschenFragen(id); }
// 🗄️ Einzelne Nachricht ins eigene Archiv: Text als Datei (Absender, Chat, Zeit) – Dateien/Fotos der Nachricht auf Wunsch mit (Archiv-Ablage-Kern)
function naInsArchiv(id) {
  const m = NA.nachrichten.get(id); if (!m) return;
  const von = m.eigen ? ICH.name : m.von, chat = typeof chatName === "function" ? chatName() : "Chat", dateien = (m.anlagen || []).filter((a) => ARCHIV_TYP_OK(a.mime));
  const titel = `Nachricht von ${von} (${zeitDe(m.zeit)})`.slice(0, 120);
  archivAblageFragen("nachricht", { frage: "Diese Nachricht in deinen Archiv-Ordner legen?", titel, datum: String(m.zeit || "").slice(0, 10) || heuteIso(), hinweis: `aus „${chat}“`,
    wahl: dateien.length ? { text: `📎 Dateien und Fotos mit ablegen (${dateien.length})` } : null,
    dateien: async (mitDateien) => {
      const aus = m.text && m.text !== "📎" ? [{ titel, name: `Nachricht-${String(m.zeit || "").slice(0, 10)}.txt`, mime: "text/plain", blob: textDatei([`Köcheclub Werne – Nachricht aus „${chat}“`, `Von: ${von}`, `Zeit: ${zeitDe(m.zeit)}`, "", m.text, "", `Abgelegt am ${zeitDe(new Date().toISOString())} von ${ICH.name}`].join("\n")), stichworte: "Text" }] : [];
      if (mitDateien || !aus.length) for (const a of dateien) { const f = await anlageAlsDatei(a); aus.push({ titel: `${a.name} (von ${von})`.slice(0, 120), name: f.name, mime: f.mime, blob: f.blob }); }
      return aus;
    } }).then((ok) => { if (!ok) melde("Archiv gerade nicht erreichbar oder noch kein eigener Archiv-Ordner – bitte später nochmal.", true); });
}
// KC-CLUB-KOPIEREN (1.8.2, Wunsch Hansi): Nachrichtentext in die Zwischenablage – z. B. um ihn in einen anderen Chat
// (auch WhatsApp) einzufügen. Ohne Clipboard-Erlaubnis: alter Kopierweg, sonst Text zum Markieren anzeigen.
async function naKopieren(id) {
  const t = String(NA.nachrichten.get(id)?.text || "");
  if (!t) return melde("Diese Nachricht hat keinen Text zum Kopieren.", true);
  const ok = () => melde("📋 Kopiert – im anderen Chat lange tippen und „Einfügen“ wählen");
  try { await navigator.clipboard.writeText(t); return ok(); } catch {}
  try {
    const ta = document.createElement("textarea"); ta.value = t; ta.setAttribute("readonly", ""); ta.style.cssText = "position:fixed;top:-1000px;opacity:0";
    document.body.appendChild(ta); ta.select(); ta.setSelectionRange(0, t.length); const g = document.execCommand("copy"); ta.remove();
    if (g) return ok();
  } catch {}
  (await eingabe("Text markieren und kopieren:", t));
}
async function reagieren(id, emoji) {
  try { await api("reaktion_setzen", { id, emoji }); chatStand = ""; await chatLaden(false); } catch (e) { meldeFehler(e); }
}
function naAntworten(id) {
  const m = NA.nachrichten.get(id); if (!m) return;
  NA.antwort = { id, von: m.eigen ? "dich" : m.von.split(" ")[0], text: String(m.text || "📎").slice(0, 90) };
  $("antwortLeiste").innerHTML = `<div class="zitat"><b>↩️ Antwort an ${esc(NA.antwort.von)}</b><span>${esc(NA.antwort.text)}</span></div><button type="button" aria-label="Antwort abbrechen" onclick="naAntwortWeg()">✕</button>`;
  $("antwortLeiste").classList.remove("versteckt"); $("text").focus();
}
function naAntwortWeg() { NA.antwort = null; $("antwortLeiste")?.classList.add("versteckt"); }
function zuNachricht(id) {
  const el = document.getElementById("msg-" + id);
  if (!el) return melde("Die Nachricht, auf die geantwortet wurde, gibt es nicht mehr.");
  el.scrollIntoView({ behavior: "smooth", block: "center" }); el.classList.add("aufblitzen"); setTimeout(() => el.classList.remove("aufblitzen"), 1600);
}
// @-Vorschläge: nur in Unterhaltungen mit mehreren anderen (in Zweiergesprächen überflüssig)
function naKandidaten() { return (CHAT?.teilnehmer || []).filter((t) => t.person_id !== ICH?.person_id); }
function naErwPruefen() {
  const box = $("erwVorschlag"), t = $("text"); if (!box || !t) return;
  const vor = t.value.slice(0, t.selectionStart ?? t.value.length), m = /(^|\s)@([\wÄÖÜäöüß-]*)$/.exec(vor);
  const kand = naKandidaten();
  if (!m || !chatId || kand.length < 2) { box.classList.add("versteckt"); return; }
  const q = m[2].toLowerCase(), treffer = kand.filter((k) => k.name.toLowerCase().split(" ").some((w) => w.startsWith(q))).slice(0, 6);
  if (!treffer.length) { box.classList.add("versteckt"); return; }
  box.innerHTML = treffer.map((k) => `<button type="button" role="option" onclick="naErwWaehlen('${k.person_id}')">@${esc(k.name)}</button>`).join("");
  box.classList.remove("versteckt");
}
function naErwWaehlen(pid) {
  const k = naKandidaten().find((x) => x.person_id === pid); if (!k) return;
  const t = $("text"), pos = t.selectionStart ?? t.value.length, vor = t.value.slice(0, pos).replace(/@([\wÄÖÜäöüß-]*)$/, ""), vn = k.name.split(" ")[0];
  t.value = vor + "@" + vn + " " + t.value.slice(pos); const neu = (vor + "@" + vn + " ").length; t.setSelectionRange(neu, neu); t.focus();
  NA.erw.set(vn, pid); $("erwVorschlag").classList.add("versteckt");
}
function naErwaehnteIds(text) { return [...NA.erw.entries()].filter(([vn]) => new RegExp("(^|\\s)@" + vn.replace(/[.*+?^${}()|[\]\\]/g, "\\$&") + "(?![\\wÄÖÜäöüß])").test(text)).map(([, id]) => id); }

// ---------- KC-CLUB-WEITERLEITEN / -RUHEZEIT / -GERAETE (0.98.0) ----------
// ↪️ Weiterleiten: Nachricht antippen → „Weiterleiten“ → Unterhaltung oder Mitglied wählen. Text bekommt den Vermerk
// „↪️ Weitergeleitet von …“, Fotos/Anhänge gehen mit (der Server prüft, dass ich die Quell-Nachricht sehen darf).
const WL = { quelle: null, liste: [] };
async function weiterleitenBlatt(id) {
  const m = NA.nachrichten.get(id); if (!m) return;
  WL.quelle = m;
  try { await zeMitglieder(); WL.liste = ((await api("unterhaltungen")).unterhaltungen || []).slice(0, 12); } catch (e) { return meldeFehler(e); }
  document.getElementById("wlFenster")?.remove();
  const f = document.createElement("div"); f.id = "wlFenster"; f.className = "blatt"; f.setAttribute("role", "dialog"); f.setAttribute("aria-modal", "true");
  f.innerHTML = `<div class="blatt-innen" style="max-height:88vh;overflow-y:auto">
    <h3>↪️ Weiterleiten an …</h3>
    <div class="na-vorschau">${esc(m.eigen ? "Du" : m.von)}: ${esc(String(m.text || "📎").slice(0, 120))}${m.anlagen?.length ? ` · 📎 ${m.anlagen.length}` : ""}</div>
    <input id="wlSuche" type="search" placeholder="🔍 Name suchen …" oninput="wlListe()">
    <div id="wlListe" class="wl-liste"></div>
    <button class="knopf" onclick="document.getElementById('wlFenster').remove()">Abbrechen</button></div>`;
  f.onclick = (e) => { if (e.target === f) f.remove(); };
  document.body.appendChild(f); wlListe();
}
function wlListe() {
  const q = ($("wlSuche")?.value || "").toLowerCase();
  const unt = WL.liste.filter((u) => u.id !== chatId).map((u) => ({ art: "t", id: u.id, name: u.gruppe ? `${u.gruppe.symbol} ${u.gruppe.name}` : (u.teilnehmer || []).join(", ") || u.betreff || "Unterhaltung" }))
    .filter((x) => !q || x.name.toLowerCase().includes(q));
  const leute = (MITGLIEDER || []).filter((m) => m.person_id !== ICH.person_id && (!q || m.name.toLowerCase().includes(q))).map((m) => ({ art: "p", id: m.person_id, name: m.name }));
  $("wlListe").innerHTML = (unt.length ? `<div class="hinweis">Letzte Unterhaltungen</div>` + unt.map((x) => `<button class="knopf" onclick="weiterleiten('${x.art}','${x.id}')">💬 ${esc(x.name)}</button>`).join("") : "")
    + (leute.length ? `<div class="hinweis" style="margin-top:6px">Mitglieder</div>` + leute.map((x) => `<button class="knopf" onclick="weiterleiten('${x.art}','${x.id}')">👤 ${esc(x.name)}</button>`).join("") : "");
}
async function weiterleiten(art, id) {
  const m = WL.quelle; if (!m) return;
  const kopf = `↪️ Weitergeleitet${m.eigen ? "" : " von " + m.von.split(" ")[0]}:`, text = m.text && m.text !== "📎" ? `${kopf}\n${m.text}` : kopf;
  const daten = { text, anlagen: (m.anlagen || []).map((a) => a.id), weiterleiten_von: m.id, wege: [] };
  // KC-CLUB-SENSIBEL-GAESTE (2.78.0): auch beim Weiterleiten fragen
  const wer = (mg) => art === "p" ? [id] : ((n) => mg.filter((x) => n.has(x.name)).map((x) => x.person_id))(new Set(WL.liste.find((u) => u.id === id)?.teilnehmer || []));
  if (!(await sensibelGaesteOk(m.text || "", m.anlagen || [], wer))) return;
  try {
    const r = art === "t" ? await api("nachricht_senden", { id, ...daten }) : await api("nachricht_senden", { ...daten, empfaenger: { personen: [id], aemter: [], alle: false, vorstand: false }, betreff: "" });
    document.getElementById("wlFenster")?.remove();
    melde("↪️ Weitergeleitet");
    WL.zuletzt = r.id;
  } catch (e) { meldeFehler(e); }
}
// 🌙 Nicht stören
function ruheZeigen() {
  const r = INIT?.einstellungen?.ruhezeit || { an: false, von: "22:00", bis: "07:00", erwaehnung: true };
  if (!$("ruheAn")) return;
  if ($("ruheAnE")) { $("ruheAnE").checked = !!r.an; $("ruheHinweisE").textContent = `${r.von}–${r.bis} Uhr kein Push (Anrufe kommen durch)`; }
  $("ruheAn").checked = !!r.an; $("ruheVon").value = r.von; $("ruheBis").value = r.bis; $("ruheErw").checked = r.erwaehnung !== false;
  document.querySelectorAll(".ruhe-zeiten input, #ruheErw").forEach((x) => { x.disabled = !r.an; });
  $("ruheHinweis").textContent = r.an ? `Von ${r.von} bis ${r.bis} Uhr kein Push. Anrufe kommen trotzdem durch; danach eine Sammelmeldung, was du verpasst hast.`
    : "In dieser Zeit kein Push. Anrufe kommen trotzdem durch, danach eine Sammelmeldung.";
}
function ruheSchnell(an) { $("ruheAn").checked = an; ruheSpeichern(); }
async function ruheSpeichern() {
  const wert = { an: $("ruheAn").checked, von: $("ruheVon").value || "22:00", bis: $("ruheBis").value || "07:00", erwaehnung: $("ruheErw").checked };
  try { const r = await api("einstellung_setzen", { schluessel: "ruhezeit", wert }); INIT.einstellungen = { ...(INIT.einstellungen || {}), ruhezeit: r.wert }; ruheZeigen();
    meinStatusZeigen(); melde(r.wert.an ? `🌙 Nicht stören: ${r.wert.von}–${r.wert.bis} Uhr` : "🔔 Nicht stören ist aus"); }
  catch (e) { meldeFehler(e); ruheZeigen(); }
}
// 📱 Meine Geräte
function geraetName(ua) {
  const sys = /iPhone/.test(ua) ? "📱 iPhone" : /iPad/.test(ua) || (/Macintosh/.test(ua) && /Mobile/.test(ua)) ? "📱 iPad" : /Android/.test(ua) ? (/Mobile/.test(ua) ? "📱 Android-Handy" : "📱 Android-Tablet") + ((/Android ([\d.]+)/.exec(ua) || [])[1] ? " " + /Android ([\d.]+)/.exec(ua)[1] : "")
    : /Windows/.test(ua) ? "💻 Windows-PC" : /Macintosh/.test(ua) ? "💻 Mac" : /Linux/.test(ua) ? "💻 Linux" : "❔ Gerät";
  const br = /SamsungBrowser/.test(ua) ? "Samsung Internet" : /Edg\//.test(ua) ? "Edge" : /Firefox|FxiOS/.test(ua) ? "Firefox" : /CriOS|Chrome/.test(ua) ? "Chrome" : /Safari/.test(ua) ? "Safari" : "";
  return sys + (br ? " · " + br : "");
}
async function geraeteBlatt() {
  let eigen = ""; try { eigen = (await (await navigator.serviceWorker.ready).pushManager.getSubscription())?.endpoint || ""; } catch {}
  let r; try { r = await api("geraete_liste", { endpoint: eigen }, { warten: true }); } catch (e) { return meldeFehler(e); }
  document.getElementById("geFenster")?.remove();
  const f = document.createElement("div"); f.id = "geFenster"; f.className = "blatt"; f.setAttribute("role", "dialog"); f.setAttribute("aria-modal", "true");
  f.innerHTML = `<div class="blatt-innen" style="max-height:88vh;overflow-y:auto">
    <h3>📱 Meine Geräte mit Push</h3>
    <p class="hinweis" style="margin:0">Alle diese Geräte bekommen deine Push-Meldungen. Ein altes Handy kannst du hier entfernen.</p>
    ${r.geraete.length ? r.geraete.map((g) => `<div class="karte innen ge-zeile${g.diesesGeraet ? " ge-dieses" : ""}">
        <div><b>${esc(geraetName(g.ua))}</b>${g.diesesGeraet ? ' <span class="marke gruen">dieses Gerät</span>' : ""}</div>
        <div class="hinweis">angemeldet seit ${esc(fKurz.format(new Date(g.seit)))}${g.zuletztZugestellt ? ` · zuletzt zugestellt ${esc(zeitKurz(g.zuletztZugestellt))}` : ""}</div>
        ${g.fehler ? `<div class="ni-fehler">⚠️ ${esc(g.fehler)}</div>` : ""}
        <button class="knopf klein" onclick="geraetEntfernen('${g.id}', ${g.diesesGeraet})">🗑️ Entfernen</button></div>`).join("")
      : '<p class="hinweis">Noch kein Gerät mit Push angemeldet. Schalte oben „📲 Push auf diesem Handy“ ein.</p>'}
    <button class="knopf" onclick="document.getElementById('geFenster').remove()">Schließen</button></div>`;
  f.onclick = (e) => { if (e.target === f) f.remove(); };
  document.body.appendChild(f);
}
async function geraetEntfernen(id, dieses) {
  if (!(await frage(dieses ? "Dieses Gerät bekommt dann keine Push-Meldungen mehr. Entfernen?" : "Dieses Gerät bekommt dann keine Push-Meldungen mehr. Entfernen?"))) return;
  try { await api("geraet_entfernen", { id }); melde("🗑️ Gerät entfernt"); if (dieses) try { await (await (await navigator.serviceWorker.ready).pushManager.getSubscription())?.unsubscribe(); } catch {} geraeteBlatt(); pushStatusZeigen?.(); }
  catch (e) { meldeFehler(e); }
}

// ---------- KC-CLUB-RECHTSCHREIBUNG (1.70.0, Wunsch Hansi): Tippfehler rot unterstreichen ----------
// Die Prüfung macht die Rechtschreibhilfe des Handys bzw. Browsers (Deutsch, kostenlos, nichts verlässt das Gerät).
// Die App schaltet sie in allen Schreibfeldern ausdrücklich ein (Deutsch, Satzanfang groß). Zeigt das Handy trotzdem
// keine rote Linie, ist die Rechtschreibprüfung in der Tastatur aus – „Prüfen“ zeigt einen Testsatz und die passende Anleitung.
const RS_AUS = new Set(["email", "password", "tel", "number", "url", "date", "time", "datetime-local", "search"]);
function rsAn(el) {
  if (!el || el.dataset.rs) return;
  const ist = el.tagName === "TEXTAREA" || (el.tagName === "INPUT" && !RS_AUS.has((el.type || "text").toLowerCase()) && !el.inputMode?.match(/numeric|decimal|tel|email/));
  if (!ist) return;
  el.dataset.rs = "1";
  if (!el.hasAttribute("spellcheck")) el.spellcheck = true;
  if (!el.hasAttribute("lang") && !el.closest("[lang]:not(html)")) el.lang = "de";
  if (el.tagName === "TEXTAREA" && !el.hasAttribute("autocapitalize")) el.setAttribute("autocapitalize", "sentences");
}
document.addEventListener("focusin", (e) => rsAn(e.target));
function rsGeraet() {
  const ua = navigator.userAgent || "";
  if (/iPhone|iPad|iPod/.test(ua) || (/Macintosh/.test(ua) && navigator.maxTouchPoints > 1)) return "ios";
  if (/SamsungBrowser|SM-[A-Z0-9]/.test(ua)) return "samsung";
  if (/Android/.test(ua)) return "android";
  return "pc";
}
const RS_ANLEITUNG = {
  android: "<b>Android:</b> Einstellungen → System → Sprachen &amp; Eingabe → Bildschirmtastatur → <b>Gboard</b> → Rechtschreibprüfung → <b>einschalten</b>. Bei manchen Handys zusätzlich: Sprachen &amp; Eingabe → „Rechtschreibprüfung“ → an, Sprache Deutsch.",
  samsung: "<b>Samsung:</b> Einstellungen → Allgemeine Verwaltung → Samsung-Tastatur-Einstellungen → Intelligente Eingabe bzw. <b>„Rechtschreibung prüfen“</b> → einschalten, Sprache Deutsch.",
  ios: "<b>iPhone/iPad:</b> Einstellungen → Allgemein → Tastatur → <b>„Rechtschreibprüfung“</b> und „Auto-Korrektur“ einschalten. Unter „Tastaturen“ sollte Deutsch dabei sein.",
  pc: "<b>PC (Chrome/Edge):</b> Rechtsklick ins Schreibfeld → Rechtschreibprüfung → <b>Deutsch</b> anhaken. Oder Einstellungen → Sprachen → Rechtschreibprüfung → an.",
};
function rsBlatt() {
  document.getElementById("rsFenster")?.remove();
  const g = rsGeraet();
  const f = document.createElement("div"); f.id = "rsFenster"; f.className = "blatt"; f.setAttribute("role", "dialog"); f.setAttribute("aria-modal", "true");
  f.innerHTML = `<div class="blatt-innen" style="max-height:88vh;overflow-y:auto">
    <h3>🖍️ Tippfehler rot unterstreichen</h3>
    <p class="hinweis" style="margin:0 0 8px">Tippe einmal in das Feld und schreib ein Wort dazu. Im Satz sind zwei Fehler versteckt.</p>
    <textarea id="rsTest" rows="3" spellcheck="true" lang="de" autocapitalize="sentences" autocorrect="on" style="width:100%;box-sizing:border-box;padding:10px;border-radius:12px;border:1px solid var(--linie);font:inherit;background:var(--karte);color:inherit">Ich freue mich auf den Weihnachtsmakrt in Werne. Bis morgn!</textarea>
    <p style="margin:10px 0 4px"><b>✅ Siehst du rote Wellenlinien unter „Weihnachtsmakrt“ und „morgn“?</b><br>Dann ist alles an. Ein Fehlerwort antippen (am PC: Rechtsklick) – dann kommen Vorschläge.</p>
    <p style="margin:10px 0 4px"><b>❌ Keine rote Linie?</b> Dann ist die Rechtschreibprüfung in der Handy-Tastatur aus. So schaltest du sie ein:</p>
    <p class="hinweis" style="margin:0 0 6px;line-height:1.5">${RS_ANLEITUNG[g]}</p>
    <details><summary class="hinweis">Andere Geräte</summary><p class="hinweis" style="line-height:1.5">${Object.keys(RS_ANLEITUNG).filter((k) => k !== g).map((k) => RS_ANLEITUNG[k]).join("<br><br>")}</p></details>
    <p class="hinweis" style="font-size:.85rem">Die Prüfung macht dein Handy selbst – kostenlos, und dein Text verlässt dabei nicht das Gerät.</p>
    <button class="knopf" onclick="document.getElementById('rsFenster').remove()">Schließen</button></div>`;
  f.onclick = (e) => { if (e.target === f) f.remove(); };
  document.body.appendChild(f);
  setTimeout(() => { const t = $("rsTest"); if (t) { t.focus(); t.setSelectionRange(t.value.length, t.value.length); } }, 150);
}

