const EMO_ZULETZT_MAX = 16;
let emoGruppe = 1;
// KC-CLUB-PINNWAND-EMOJI (1.94.0): derselbe Emoji-Kern für weitere Schreibfelder (zuerst Pinnwand-Zettel) – Ziel + Bausteine je Feld
const EMO_ORTE = { text: { feld: "emoFeld", reiter: "emoReiter", gitter: "emoGitter", knopf: "emoKnopf" }, pwText: { feld: "pwEmoFeld", reiter: "pwEmoReiter", gitter: "pwEmoGitter", knopf: "pwEmoKnopf", nachher: () => pwZaehlen() } };
let emoZiel = "text";
const emoOrt = () => EMO_ORTE[emoZiel] || EMO_ORTE.text;
function emoZuletzt() { try { return JSON.parse(localStorage.getItem("kc_club_emoji_zuletzt") || "[]").slice(0, EMO_ZULETZT_MAX); } catch { return []; } }
function emoUmschalten(an, ziel) {
  if (ziel && ziel !== emoZiel) { const alt = emoOrt(); $(alt.feld)?.classList.add("versteckt"); $(alt.knopf)?.setAttribute("aria-expanded", "false"); emoZiel = ziel; }
  const o = emoOrt(), f = $(o.feld); if (!f) return;
  const offen = an ?? f.classList.contains("versteckt");
  f.classList.toggle("versteckt", !offen); $(o.knopf)?.setAttribute("aria-expanded", String(offen));
  if (offen) { emoGruppe = emoZuletzt().length ? 0 : 1; emoZeichnen(); } // startet mit „Zuletzt“, sonst Gesichter
}
function emoZeichnen() {
  const zul = emoZuletzt();
  const o = emoOrt();
  $(o.reiter).innerHTML = EMO_GRUPPEN.map((g, i) => (i === 0 && !zul.length) ? "" :
    `<button type="button" class="${i === emoGruppe ? "an" : ""}" title="${esc(g.name)}" aria-label="${esc(g.name)}" onclick="emoGruppe=${i};emoZeichnen()">${g.sym}</button>`).join("")
    + `<button type="button" class="emo-zu" title="Schließen" aria-label="Emoji-Auswahl schließen" onclick="emoUmschalten(false)">✕</button>`;
  const liste = emoGruppe === 0 ? zul : EMO_GRUPPEN[emoGruppe].liste;
  $(o.gitter).innerHTML = liste.map((e) => `<button type="button" onclick="emoEinfuegen('${e}')">${e}</button>`).join("");
}
// Schreibstelle merken: beim Antippen der Emoji-Knöpfe verliert das Feld den Fokus, manche Browser setzen die Stelle dann zurück
let emoStelle = null;
function emoStelleMerken(ziel) { if (ziel) emoZiel = ziel; const t = $(emoZiel); if (t) emoStelle = [t.selectionStart ?? t.value.length, t.selectionEnd ?? t.value.length, t.value]; }
function emoEinfuegen(e, ziel) {
  if (ziel && ziel !== emoZiel) { emoZiel = ziel; emoStelle = null; }
  const t = $(emoZiel); if (!t) return;
  if (t.maxLength > 0 && t.value.length + e.length > t.maxLength) return melde("Der Zettel ist voll – für das Emoji bitte etwas Text kürzen.", true);
  let [a, b] = emoStelle && emoStelle[2] === t.value ? emoStelle : [t.selectionStart ?? t.value.length, t.selectionEnd ?? t.value.length];
  if (document.activeElement === t) { a = t.selectionStart; b = t.selectionEnd; }
  t.value = t.value.slice(0, a) + e + t.value.slice(b);
  const pos = a + e.length; t.setSelectionRange?.(pos, pos); emoStelle = [pos, pos, t.value];
  t.style.height = "auto"; t.style.height = t.scrollHeight + "px";
  try { const z = [e, ...emoZuletzt().filter((x) => x !== e)].slice(0, EMO_ZULETZT_MAX); localStorage.setItem("kc_club_emoji_zuletzt", JSON.stringify(z)); } catch {}
  if (emoGruppe === 0 && !$(emoOrt().feld)?.classList.contains("versteckt")) emoZeichnen();
  emoOrt().nachher?.(); if (emoZiel === "text") tippenMelden?.();
}
// Tippen außerhalb schließt die Auswahl
// (Knöpfe im Feld werden beim Umschalten neu gezeichnet – ein so entfernter Knopf zählt nicht als „daneben“.)
document.addEventListener("click", (ev) => { const o = emoOrt(), f = $(o.feld); if (f && !f.classList.contains("versteckt") && ev.target.isConnected && !ev.target.closest(`#${o.feld},#${o.knopf}`)) emoUmschalten(false); });

// ---------- KC-CLUB-NACHRICHT-INFO (0.94.0): Nachricht antippen → wann, auf welchem Weg raus, angekommen, gelesen ----------
const NI_KANAL = { push: "🔔 Push aufs Handy", email: "✉️ E-Mail", sms: "💬 SMS", whatsapp: "🟢 WhatsApp" };
const NI_SCHRITT = {
  queued: "⏳ in der Warteschlange", processing: "⚙️ wird verschickt", sent: "📤 verschickt", delivered: "📥 angekommen",
  displayed: "👀 auf dem Handy angezeigt", opened: "👆 angetippt / geöffnet", failed: "❌ fehlgeschlagen", retry: "🔁 neuer Versuch geplant", dead_letter: "🛑 aufgegeben",
};
const NI_ANBIETER = { webde: "über web.de", "web-push": "über den Push-Dienst", client: "vom Handy gemeldet" };
function niZeit(iso) { if (!iso) return "–"; const d = new Date(iso); return `${fTag.format(d)}, ${fZeit.format(d)}:${String(d.getSeconds()).padStart(2, "0")} Uhr`; }
function niStatusText(w) {
  if (w.aufgegeben) return "🛑 aufgegeben – ist nicht angekommen";
  if (w.status === "opened") return "👆 geöffnet";
  if (w.status === "displayed") return "👀 auf dem Handy angezeigt";
  if (w.status === "delivered") return "📥 angekommen";
  if (w.status === "sent") return w.kanal === "email" ? "📤 vom Mail-Server angenommen" : "📤 verschickt";
  if (w.status === "failed") return "❌ fehlgeschlagen";
  return "⏳ " + (w.status || "unterwegs");
}
async function nachrichtInfo(id) {
  let r; try { r = await api("nachricht_details", { id }, { warten: true }); } catch (e) { return meldeFehler(e); }
  document.getElementById("niFenster")?.remove();
  const f = document.createElement("div"); f.id = "niFenster"; f.className = "blatt"; f.setAttribute("role", "dialog"); f.setAttribute("aria-modal", "true");
  const gel = r.empfaenger.filter((e) => e.gelesen).length;
  const empf = r.empfaenger.map((e) => `<div class="ni-zeile"><span>${e.gelesen ? "✓✓" : "✓"} <b>${esc(e.name)}</b></span><span class="hinweis">${e.gelesen ? "in der App gelesen" + (e.zuletztGeoeffnet ? ` (zuletzt geöffnet ${esc(niZeit(e.zuletztGeoeffnet))})` : "") : "in der App noch nicht gelesen"}</span></div>`).join("");
  const wege = !r.wegeSichtbar ? "" : !r.wege.length
    ? `<p class="hinweis" style="margin:0">Kein Push und keine E-Mail verschickt – die Nachricht steht nur in der App (z. B. weil der Empfänger Benachrichtigungen für Nachrichten ausgeschaltet hat oder gerade in der Unterhaltung war).</p>`
    : r.wege.map((w) => `<div class="karte innen ni-weg">
        <div><b>${NI_KANAL[w.kanal] || esc(w.kanal)}</b> an ${esc(w.an.join(", "))}</div>
        <div class="ni-status">${niStatusText(w)}</div>
        <ol class="ni-verlauf">${[{ typ: "erstellt", zeit: w.erstellt }, ...w.ereignisse].map((e) => `<li><span>${e.typ === "erstellt" ? "📝 in Auftrag gegeben" : NI_SCHRITT[e.typ] || esc(e.typ)}${e.anbieter && NI_ANBIETER[e.anbieter] ? " " + NI_ANBIETER[e.anbieter] : ""}</span><span class="hinweis">${esc(niZeit(e.zeit))}</span></li>`).join("")}</ol>
        ${w.fehler ? `<div class="ni-fehler">⚠️ ${esc(w.fehler)}</div>` : ""}
        ${w.versuche > 1 ? `<div class="hinweis">${w.versuche} Versuche</div>` : ""}${w.naechsterVersuch ? `<div class="hinweis">Nächster Versuch: ${esc(niZeit(w.naechsterVersuch))}</div>` : ""}
        ${w.kanal === "email" && !w.aufgegeben && w.status === "sent" ? `<div class="hinweis" style="font-size:.8rem">Ob die Mail geöffnet wurde, meldet ein Postfach nicht zurück.</div>` : ""}</div>`).join("");
  f.innerHTML = `<div class="blatt-innen" style="max-height:88vh;overflow-y:auto">
    <h3>ℹ️ Nachricht – Einzelheiten</h3>
    ${r.wichtig ? '<div class="ni-zeile ni-wichtig"><span>❗ <b>Wichtige Nachricht</b></span><span>Wichtigkeit: hoch</span></div>' : ""}
    <div class="ni-zeile"><span>✍️ Geschrieben ${r.eigen ? "von dir" : "von " + esc(r.von)}</span><span class="hinweis">${esc(niZeit(r.zeit))}</span></div>
    <b>👥 Empfänger${r.empfaenger.length > 1 ? ` – ${gel} von ${r.empfaenger.length} gelesen` : ""}</b>${empf || '<p class="hinweis" style="margin:0">Nur du (Test-Unterhaltung)</p>'}
    ${r.wegeSichtbar ? `<b>🚚 Zustellung</b>${wege}` : ""}
    <button class="knopf" onclick="document.getElementById('niFenster').remove()">Schließen</button></div>`;
  f.onclick = (e) => { if (e.target === f) f.remove(); };
  document.body.appendChild(f);
}

// ---------- KC-CLUB-SOS (1.6.0, Wunsch Hansi): Notrufnummern und Kontakte im Notfall ----------
// Jede Notrufnummer wird erst nach einer deutlichen Rückfrage („das ist ein ECHTER Anruf“) gewählt – nie direkt per Link.
// Kontakte: nur, was ein Mitglied selbst freigegeben hat; Notfallkontakte sieht wie bisher nur die Clubleitung.
const NOTRUFE = [
  { nr: "112", anzeige: "112", t: "Feuerwehr & Rettungsdienst", u: "Lebensgefahr, Unfall, Feuer", sym: "🚑", haupt: true },
  { nr: "110", anzeige: "110", t: "Polizei", u: "Gefahr, Straftat, Unfall mit Verletzten", sym: "🚓", haupt: true },
  { nr: "116117", anzeige: "116 117", t: "Ärztlicher Bereitschaftsdienst", u: "nicht lebensbedrohlich, außerhalb der Sprechzeiten", sym: "🩺" },
  { nr: "022819240", anzeige: "0228 19240", t: "Giftnotruf NRW (Bonn)", u: "Vergiftung – rund um die Uhr", sym: "☠️" },
  { nr: "08000022833", anzeige: "0800 00 22 8 33", t: "Apotheken-Notdienst", u: "nächste geöffnete Apotheke", sym: "💊" },
  { nr: "08001110111", anzeige: "0800 111 0 111", t: "Telefonseelsorge", u: "kostenlos, rund um die Uhr", sym: "🤝" },
  { nr: "116116", anzeige: "116 116", t: "Sperr-Notruf", u: "Bank- und Kreditkarten sperren", sym: "💳" },
];
let SOS = { daten: null, suche: "", offen: null, wo: null };
function sosStart() { SOS.suche = ""; SOS.offen = null; SOS.wo = null; zeige("sos"); sosZeigen(); sosLaden(); }
async function sosLaden() { try { SOS.daten = await api("sos_kontakte"); sosZeigen(); } catch (e) { SOS.daten = { fehler: e.message }; sosZeigen(); } }
async function sosAnrufen(nr) {
  const n = NOTRUFE.find((x) => x.nr === nr); if (!n) return;
  if (!(await frage(`⚠️ ECHTER ANRUF – KEIN TEST\n\nDein Telefon wählt jetzt wirklich ${n.anzeige}\n(${n.t}).\n\nNur im echten Notfall. Jetzt anrufen?`))) return;
  location.href = "tel:" + n.nr;
}
const sosNummer = (t) => String(t || "").replace(/[^\d+]/g, "");
function sosWhatsapp(t) { let n = sosNummer(t); if (n.startsWith("+")) n = n.slice(1); else if (n.startsWith("00")) n = n.slice(2); else if (n.startsWith("0")) n = "49" + n.slice(1); return "https://wa.me/" + n; }
function sosKnoepfe(k) {
  const b = (href, text, extern) => `<a class="knopf klein" href="${esc(href)}"${extern ? ' target="_blank" rel="noopener"' : ""}>${text}</a>`;
  return [k.handy ? b("tel:" + sosNummer(k.handy), "📞 Handy") + b("sms:" + sosNummer(k.handy), "💬 SMS") + b(sosWhatsapp(k.handy), "🟢 WhatsApp", true) : "",
    k.festnetz ? b("tel:" + sosNummer(k.festnetz), "☎️ Festnetz") : "", k.mail ? b("mailto:" + k.mail, "✉️ E-Mail") : ""].join("");
}
function sosInfo(id) {
  const d = SOS.daten, m = d?.mitglieder?.find((x) => x.id === id); if (!m) return;
  const k = m.kontakt || {}, hat = k.handy || k.festnetz || k.mail;
  if (m.selbst) return blattAuf("sosInfo", `<h3 style="margin-top:0">${esc(m.name)} <small class="hinweis">(du)</small></h3>
    ${m.notfall ? `<div class="sos-nf sos-nf-gross" style="margin-top:0"><b>🆘 Dein Notfallkontakt: ${esc(m.notfall.name || "–")}</b>${m.notfall.beziehung ? ` <span>(${esc(m.notfall.beziehung)})</span>` : ""}${m.notfall.telefon ? `<div>📞 ${esc(m.notfall.telefon)}</div>` : ""}</div>`
      : '<div class="karte hinweis" style="margin:0">⚠️ Du hast noch keinen Notfallkontakt hinterlegt.</div>'}
    <p class="hinweis" style="font-size:.85rem">🔒 Deinen Notfallkontakt sehen nur du und die Clubleitung (Clubsprecher, Kassenwart, Admin).</p>
    <button class="knopf haupt" style="width:100%;text-align:center" onclick="$('sosInfo').remove();einstiegHin('privat','nfName')">✏️ ${m.notfall ? "Notfallkontakt ändern" : "Notfallkontakt eintragen"}</button>
    <button class="knopf" style="width:100%;text-align:center;margin-top:8px" onclick="$('sosInfo').remove()">Schließen</button>`);
  blattAuf("sosInfo", `<h3 style="margin-top:0">${esc(m.name)}${m.aemter?.length ? ` <span class="marke">${esc(m.aemter.join(", "))}</span>` : ""}</h3>
    ${hat ? `<div class="knoepfe">${sosKnoepfe(k)}</div>` : '<p class="hinweis" style="margin:0">Keine freigegebenen Kontaktdaten.</p>'}
    ${d.siehtNotfall ? (m.notfall ? `<div class="sos-nf sos-nf-gross"><b>🆘 Notfallkontakt: ${esc(m.notfall.name || "–")}</b>${m.notfall.beziehung ? ` <span>(${esc(m.notfall.beziehung)})</span>` : ""}
        ${m.notfall.telefon ? `<div class="knoepfe">${sosKnoepfe({ handy: m.notfall.telefon })}</div>` : ""}</div><p class="hinweis" style="font-size:.85rem">🔒 Den Notfallkontakt sieht nur die Clubleitung.</p>` : '<p class="hinweis" style="margin:10px 0 0">Kein Notfallkontakt hinterlegt.</p>')
      : '<p class="hinweis" style="margin:10px 0 0">🔒 Den Notfallkontakt sieht nur die Clubleitung (Clubsprecher, Kassenwart, Admin) – bitte dort anrufen.</p>'}
    <button class="knopf" style="width:100%;text-align:center;margin-top:10px" onclick="$('sosInfo').remove()">Schließen</button>`);
}
function sosZeigen() {
  if (!$("sosInhalt")) return;
  const d = SOS.daten, nf = INIT?.notfall;
  const notrufe = `${sosDarf() ? `<button class="knopf alarm-knopf" style="width:100%;margin-bottom:8px" onclick="notfallMeldung()">🚨 Alarm an alle Mitglieder${ICH?.admin && !INIT?.sosFuerAlle ? " (nur Admin)" : ""}</button>` : ""}<div class="karte sos-warn"><b>🚨 Bei Lebensgefahr sofort 112 anrufen.</b><div class="hinweis" style="color:inherit;opacity:.9">Beim Antippen fragt die App einmal nach – dann wird wirklich gewählt.</div></div>
    <div class="sos-nummern">${NOTRUFE.map((n) => `<button class="sos-nr${n.haupt ? " haupt" : ""}" onclick="sosAnrufen('${n.nr}')"><span class="sym">${n.sym}</span>
      <span class="txt"><b>${esc(n.anzeige)}</b><span>${esc(n.t)}</span><small>${esc(n.u)}</small></span><span class="ruf">📞</span></button>`).join("")}</div>`;
  const eigen = nf ? "" : `<div class="karte hinweis">🆘 Du hast noch keinen eigenen Notfallkontakt hinterlegt. <button class="knopf klein" onclick="einstiegHin('privat','nfName')">Jetzt eintragen</button></div>`;
  let kontakte;
  if (!d) kontakte = '<p class="hinweis">Kontakte werden geladen …</p>';
  else if (d.fehler) kontakte = `<div class="karte hinweis">⚠️ ${esc(d.fehler)}</div>`;
  else {
    const q = suNorm(SOS.suche), liste = d.mitglieder.filter((m) => !m.selbst && (!q || suNorm(m.name).includes(q)));
    const leitung = d.mitglieder.filter((m) => m.leitung && !m.selbst);
    const zeile = (m) => {
      const offen = SOS.offen === m.id, k = m.kontakt || {}, hat = k.handy || k.festnetz || k.mail;
      return `<div class="sos-mitglied${offen ? " offen" : ""}"><button class="sos-name" onclick="SOS.offen=SOS.offen==='${m.id}'?null:'${m.id}';sosZeigen()"><b>${esc(m.name)}</b>${m.aemter?.length ? `<small>${esc(m.aemter.join(" · "))}</small>` : ""}${d.siehtNotfall && m.notfall ? '<small class="nf-ja">🆘</small>' : ""}<span>${offen ? "▴" : "▾"}</span></button>
        ${offen ? `<div class="sos-detail">${hat ? `<div class="knoepfe">${sosKnoepfe(k)}</div>` : '<p class="hinweis" style="margin:0">Keine freigegebenen Kontaktdaten.</p>'}
          ${d.siehtNotfall ? (m.notfall ? `<div class="sos-nf"><b>🆘 Notfallkontakt: ${esc(m.notfall.name || "–")}</b>${m.notfall.beziehung ? ` <span class="hinweis">(${esc(m.notfall.beziehung)})</span>` : ""}
              ${m.notfall.telefon ? `<div class="knoepfe">${sosKnoepfe({ handy: m.notfall.telefon })}</div>` : ""}</div>` : '<p class="hinweis" style="margin:6px 0 0">Kein Notfallkontakt hinterlegt.</p>')
            : '<p class="hinweis" style="margin:6px 0 0">🔒 Den Notfallkontakt sieht nur die Clubleitung (Clubsprecher, Kassenwart, Admin) – bitte dort anrufen.</p>'}</div>` : ""}</div>`;
    };
    // KC-CLUB-SOS-KACHELN (1.49.0): Mitglieder als Kacheln (wählbar: Kacheln | Liste, gleiche Einstellung wie bei Mitglieder);
    // Notfallkontakt rot markiert – das sieht wie bisher nur die Clubleitung (siehtNotfall), alle anderen nur Name/Amt/erreichbar
    const kachelAn = MG_ANSICHT !== "liste"; // 2.23.89: Anwesenheitstafel gibt es nur bei Mitglieder – SOS zeigt dann Kacheln
    // eigener Notfallkontakt: sieht jeder bei sich selbst (Server liefert ihn immer für einen selbst)
    const kachel = (m, leit) => { const k = m.kontakt || {}, hat = k.handy || k.festnetz || k.mail, zeigNf = d.siehtNotfall || m.selbst, nfJa = zeigNf && m.notfall;
      return `<button class="mini-kachel sos-k${nfJa ? " hat-nf" : ""}${leit ? " leit" : ""}${m.selbst ? " selbst" : ""}" onclick="sosInfo('${m.id}')"><span class="avatar sos-av" style="width:46px;height:46px">${esc(initialen(m.name))}</span>
        <span class="mk-titel">${esc(m.name)}${m.selbst ? " <small>(du)</small>" : ""}</span>${m.aemter?.length ? `<span class="marke">${esc(m.aemter.join(", "))}</span>` : ""}
        ${zeigNf ? (nfJa ? '<span class="nf-ja">🆘 Notfallkontakt</span>' : `<span class="mk-unter">${m.selbst ? "⚠️ noch kein Notfallkontakt" : "kein Notfallkontakt"}</span>`) : ""}
        ${m.selbst ? '<span class="mk-unter">✏️ antippen zum Prüfen</span>' : `<span class="mk-unter">${hat ? "📞 erreichbar" : "🔒 keine Nummer frei"}</span>`}</button>`; };
    const ich = d.mitglieder.find((m) => m.selbst && (!q || suNorm(m.name).includes(q)));
    const ichZeile = (m) => `<div class="sos-mitglied"><button class="sos-name" onclick="sosInfo('${m.id}')"><b>${esc(m.name)}</b><small>(du)</small>${m.notfall ? '<small class="nf-ja">🆘</small>' : '<small>⚠️ noch kein Notfallkontakt</small>'}<span>›</span></button></div>`;
    const block = (l, leit, mitIch) => kachelAn ? `<div class="mini-kacheln">${mitIch && ich ? kachel(ich) : ""}${l.map((m) => kachel(m, leit)).join("")}</div>` : `<div class="karte">${mitIch && ich ? ichZeile(ich) : ""}${l.map(zeile).join("")}</div>`;
    const schalter = `<div class="umschalter sos-ansicht" id="sosAnsicht" data-zyklus="Ansicht" data-zyklus-kurz><button data-a="kacheln" data-zk-text="🔲 Kacheln" class="${kachelAn ? "an" : ""}" onclick="mgAnsichtSetzen('kacheln')" title="Als Kacheln zeigen" aria-label="Als Kacheln zeigen">🔲</button><button data-a="liste" data-zk-text="☰ Liste" class="${kachelAn ? "" : "an"}" onclick="mgAnsichtSetzen('liste')" title="Als Liste zeigen" aria-label="Als Liste zeigen">☰</button></div>`;
    kontakte = (leitung.length && !d.siehtNotfall ? `<h3 style="margin:16px 4px 6px">⭐ Clubleitung</h3>${block(leitung, true)}` : "")
      + `<div class="sos-kopf"><h3>👥 Mitglieder im Notfall erreichen</h3>${schalter}</div>
      ${d.siehtNotfall && kachelAn ? '<p class="hinweis" style="margin:0 4px 8px;font-size:.85rem"><span class="nf-ja">🆘</span> = Notfallkontakt hinterlegt (rot umrandet) · antippen für Anrufen, SMS, WhatsApp</p>' : ""}
      <input id="sosSuche" type="search" placeholder="🔍 Name suchen …" autocomplete="off" value="${esc(SOS.suche)}" oninput="SOS.suche=this.value;sosZeigen();$('sosSuche').focus();$('sosSuche').setSelectionRange(this.value.length,this.value.length)">
      ${liste.length || ich ? block(liste, false, true) : '<div class="karte"><p class="hinweis">Niemand gefunden.</p></div>'}`;
  }
  $("sosInhalt").innerHTML = notrufe + sosWoKarte() + nfpKarte() + eigen + kontakte;
}

// ---------- KC-CLUB-SOS-WO (1.7.0, Wunsch Hansi): „📍 Wo bin ich?“ – eigener Standort mit Adresse zum Vorlesen am Telefon
// oder zum Verschicken (SMS, WhatsApp, kopieren). Nur auf Knopfdruck, nichts wird gespeichert, kein Live-Teilen.
// Adresse über den Server (gleicher kostenloser OpenStreetMap-Adapter wie bei Fotos); Koordinaten gelten auch ohne Adresse.
function sosWoKarte() {
  const w = SOS.wo;
  if (!w) return `<div class="karte"><b>📍 Wo bin ich?</b><div class="hinweis">Zeigt deinen Standort mit Adresse – zum Vorlesen am Telefon oder zum Schicken. Wird nicht gespeichert.</div>
    <button class="knopf haupt" style="margin-top:8px" onclick="sosWoBinIch()">📍 Standort jetzt bestimmen</button></div>`;
  if (w.fehler && !w.lat) return `<div class="karte"><b>📍 Wo bin ich?</b><div class="hinweis">⚠️ ${esc(w.fehler)}</div><button class="knopf" style="margin-top:8px" onclick="sosWoBinIch()">🔄 Noch einmal</button></div>`;
  const koord = `${w.lat.toFixed(5)}, ${w.lon.toFixed(5)}`;
  return `<div class="karte"><b>📍 Hier bin ich</b> <span class="hinweis">(${esc(w.zeit)} Uhr · auf ca. ${w.genau} m genau)</span>
    <div class="sos-wo-adr">${w.adresse ? esc(w.adresse) : w.laedt ? "Adresse wird gesucht …" : "Adresse nicht gefunden"}</div>
    <div class="sos-wo-koord">${koord}</div>${w.adresse && /Nachbarhaus/.test(w.adresse) ? '<div class="hinweis">GPS ist auf einige Meter ungenau – bitte die Hausnummer vor Ort kurz prüfen.</div>' : ""}${w.adrFehler ? `<div class="hinweis">${esc(w.adrFehler)}</div>` : ""}
    <div class="knoepfe" style="margin-top:8px"><button class="knopf klein" onclick="sosWoKopieren()">📋 Kopieren</button>
      <a class="knopf klein" href="${esc("sms:?&body=" + encodeURIComponent(sosWoText()))}">💬 SMS</a>
      <a class="knopf klein" href="${esc("https://wa.me/?text=" + encodeURIComponent(sosWoText()))}" target="_blank" rel="noopener">🟢 WhatsApp</a>
      <a class="knopf klein" href="${esc(stKarte(w.lat.toFixed(5), w.lon.toFixed(5)))}" target="_blank" rel="noopener">🗺️ Karte</a>
      <button class="knopf klein" onclick="sosWoBinIch()">🔄 Neu</button></div></div>`;
}
function sosWoText() {
  const w = SOS.wo; if (!w?.lat) return "";
  return `Mein Standort (${w.zeit} Uhr): ${w.adresse ? w.adresse + " – " : ""}${w.lat.toFixed(5)}, ${w.lon.toFixed(5)} – Karte: ${stKarte(w.lat.toFixed(5), w.lon.toFixed(5))}`;
}
function sosWoKopieren() { const t = sosWoText(); navigator.clipboard?.writeText(t).then(() => melde("📋 Standort kopiert"), async () => (await eingabe("Standort:", t))); }
async function sosWoBinIch() {
  let p;
  try { p = await stPositionWarten(); } catch (e) { SOS.wo = { fehler: e.message }; sosZeigen(); return; }
  const c = p.coords, zeit = new Date().toLocaleTimeString("de-DE", { hour: "2-digit", minute: "2-digit" });
  SOS.wo = { lat: c.latitude, lon: c.longitude, genau: Math.max(1, Math.round(c.accuracy || 0)), zeit, laedt: true };
  sosZeigen();
  const w = SOS.wo;
  try { const r = await api("sos_ort", { lat: w.lat, lon: w.lon, genau: w.genau }, { warten: true }); w.adresse = r.adresse || null; if (r.fehler) w.adrFehler = r.fehler; }
  catch (e) { w.adrFehler = e.message; }
  w.laedt = false; if (SOS.wo === w) sosZeigen();
}

// ---------- KC-CLUB-NOTFALLPASS (1.7.0, Wunsch Hansi): freiwillige Gesundheitsangaben zum Vorzeigen im Notfall.
// Gesundheitsdaten sind besonders schützenswert → sie bleiben NUR auf diesem Gerät (localStorage je Person), gehen nie an
// den Server, nicht in die Sicherung und nicht nach Neon. Niemand sonst sieht sie – auch die Clubleitung nicht.
// Hinweis auf den Notfallpass des Handys (Sperrbildschirm), weil die Club-App bei gesperrtem Handy nicht erreichbar ist.
const NFP_FELDER = [
  { k: "geburt", t: "Geburtsdatum", typ: "date" },
  { k: "blut", t: "Blutgruppe", typ: "wahl", w: ["", "0 Rh+", "0 Rh−", "A Rh+", "A Rh−", "B Rh+", "B Rh−", "AB Rh+", "AB Rh−", "weiß ich nicht"] },
  { k: "allergien", t: "Allergien / Unverträglichkeiten", typ: "lang", bsp: "z. B. Penicillin, Nüsse, Wespenstich" },
  { k: "erkrankungen", t: "Vorerkrankungen", typ: "lang", bsp: "z. B. Diabetes, Herz, Asthma, Epilepsie" },
  { k: "medikamente", t: "Medikamente", typ: "lang", bsp: "z. B. Blutverdünner, Insulin" },
  { k: "hinweise", t: "Wichtig für Helfer", typ: "lang", bsp: "z. B. Herzschrittmacher, Notfallspray in der Jackentasche" },
  { k: "arzt", t: "Hausarzt (Name und Telefon)", bsp: "z. B. Dr. Muster, 02389 …" },
  { k: "kasse", t: "Krankenkasse", bsp: "z. B. AOK" },
  { k: "organspende", t: "Organspende", typ: "wahl", w: ["", "Ausweis ist dabei", "im Organspende-Register eingetragen", "nein", "keine Angabe"] },
];
const nfpSchluessel = () => "kc_club_notfallpass_" + (ICH?.person_id || "x");
function nfpLesen() { try { const d = JSON.parse(localStorage.getItem(nfpSchluessel()) || "null"); return d && typeof d === "object" ? d : null; } catch { return null; } }
function nfpGefuellt(d) { return !!d && NFP_FELDER.some((f) => String(d[f.k] || "").trim()); }
function nfpKarte() {
  const d = nfpLesen(), voll = nfpGefuellt(d);
  return `<div class="karte"><b>🪪 Mein Notfallpass</b><div class="hinweis">${voll ? "Zum Vorzeigen für Helfer und Rettungsdienst." : "Allergien, Medikamente, Blutgruppe … – freiwillig."} 🔒 Nur auf diesem Gerät gespeichert, niemand sonst sieht ihn.</div>
    <div class="knoepfe" style="margin-top:8px">${voll ? `<button class="knopf haupt" onclick="nfpZeigen()">🪪 Notfallpass zeigen</button><button class="knopf klein" onclick="nfpBearbeiten()">✏️ Ändern</button>` : `<button class="knopf haupt" onclick="nfpBearbeiten()">✏️ Notfallpass ausfüllen</button>`}</div></div>`;
}
function nfpZu() { $("nfpBlatt").classList.add("versteckt"); }
function nfpWert(f, v) { if (f.typ === "date" && /^\d{4}-\d{2}-\d{2}$/.test(v)) return v.split("-").reverse().join("."); return v; }
function nfpZeigen() {
  const d = nfpLesen() || {}, nf = INIT?.notfall;
  const zeilen = NFP_FELDER.filter((f) => String(d[f.k] || "").trim()).map((f) => `<div class="nfp-zeile"><small>${esc(f.t)}</small><b>${esc(nfpWert(f, String(d[f.k]).trim()))}</b></div>`).join("");
  $("nfpInhalt").innerHTML = `<div class="nfp-pass"><h3>🆘 NOTFALLPASS</h3>
      <div class="nfp-zeile"><small>Name</small><b>${esc(ICH?.name || "")}</b></div>${zeilen}
      ${nf?.name || nf?.telefon ? `<div class="nfp-zeile"><small>Notfallkontakt${nf.beziehung ? " (" + esc(nf.beziehung) + ")" : ""}</small><b>${esc(nf.name || "")}${nf.telefon ? " · " + esc(nf.telefon) : ""}</b></div>` : ""}</div>
    <p class="hinweis">Stand: ${esc(d.stand ? new Date(d.stand).toLocaleDateString("de-DE") : "–")}</p>
    <button class="knopf" style="text-align:center" onclick="nfpArchivWahl()">🗄️ In mein Archiv kopieren</button>
    <button class="knopf" style="text-align:center" onclick="nfpZu()">Schließen</button>`;
  $("nfpBlatt").classList.remove("versteckt");
}
function nfpBearbeiten() {
  const d = nfpLesen() || {};
  const feld = (f) => {
    const v = esc(String(d[f.k] || "")), id = "nfp_" + f.k;
    if (f.typ === "wahl") return `<label class="feld">${esc(f.t)}<select id="${id}">${f.w.map((x) => `<option value="${esc(x)}"${x === String(d[f.k] || "") ? " selected" : ""}>${x ? esc(x) : "– bitte wählen –"}</option>`).join("")}</select></label>`;
    if (f.typ === "lang") return `<label class="feld">${esc(f.t)}<textarea id="${id}" maxlength="500" placeholder="${esc(f.bsp || "")}">${v}</textarea></label>`;
    return `<label class="feld">${esc(f.t)}<input id="${id}" ${f.typ === "date" ? 'type="date"' : 'maxlength="120"'} placeholder="${esc(f.bsp || "")}" value="${v}"></label>`;
  };
  $("nfpInhalt").innerHTML = `<h3 style="margin-top:0">🪪 Notfallpass ausfüllen</h3>
    <p class="hinweis">Alles freiwillig – nur ausfüllen, was Helfern im Notfall nützt. 🔒 Die Angaben bleiben <b>nur auf diesem Gerät</b>: Sie gehen nicht an den Club, nicht an die Clubleitung und nicht in die Sicherung. Auf einem neuen Handy musst du sie neu eintragen.</p>
    <div id="nfpForm">${NFP_FELDER.map(feld).join("")}</div>
    <p class="hinweis">🆘 Der Notfallkontakt kommt aus deinen Einstellungen${INIT?.notfall?.name ? ` (${esc(INIT.notfall.name)})` : " – noch keiner eingetragen"}.</p>
    <p class="hinweis">📱 Tipp: Trag das Wichtigste auch im Notfallpass deines Handys ein – den sehen Helfer auch bei gesperrtem Handy. iPhone: App „Health“ → Profilbild → Notfallpass. Android: Einstellungen → Sicherheit und Notfall → Medizinische Informationen.</p>
    <button class="knopf haupt" style="text-align:center" onclick="nfpSpeichern()">💾 Speichern</button>
    <div class="zwei"><button class="knopf" style="text-align:center" onclick="nfpZu()">Abbrechen</button>${nfpGefuellt(d) ? '<button class="knopf" style="text-align:center" onclick="nfpLoeschen()">🗑️ Löschen</button>' : ""}</div>`;
  $("nfpBlatt").classList.remove("versteckt");
}
function nfpSpeichern() {
  const d = { stand: new Date().toISOString() };
  for (const f of NFP_FELDER) { const v = String($("nfp_" + f.k)?.value || "").trim().slice(0, 500); if (v) d[f.k] = v; }
  try { localStorage.setItem(nfpSchluessel(), JSON.stringify(d)); } catch { melde("Speichern auf diesem Gerät ist nicht möglich (privates Surfen?).", true); return; }
  nfpZu(); melde("🪪 Notfallpass auf diesem Gerät gespeichert"); sosZeigen();
}
async function nfpLoeschen() {
  if (!(await frage("Notfallpass auf diesem Gerät löschen?"))) return;
  try { localStorage.removeItem(nfpSchluessel()); } catch {}
  nfpZu(); melde("Notfallpass gelöscht"); sosZeigen();
}

// ---------- KC-CLUB-NOTFALLPASS-ARCHIV (1.17.0, Wunsch Hansi): Notfallpass als Bild in den EIGENEN Archiv-Ordner kopieren ----------
// Nur auf ausdrücklichen Wunsch (Warnhinweis: danach liegt die Kopie auch auf dem Server, im Spiegel und in Sicherungen).
// Ziel sind nur eigene Ordner (besitzer = ich); das Register wird gewählt (kein Freitext). Der Pass auf dem Handy bleibt unverändert.
// Kein neuer Serverweg: archiv_liste + archiv_hochladen (Rechte, 50-MB-Grenze und Dateityp prüft der Server wie bei jedem Upload).
const NFP_ARCHIV_REGISTER_VORSCHLAG = ["Gesundheit", "Sonstiges"];
let NFP_AR = null;
const nfpEigeneOrdner = (d) => (d?.ordner || []).filter((o) => o.besitzer && o.eigen).sort((a, b) => b.jahr - a.jahr);
function nfpStandText(d) { return new Date(d?.stand || Date.now()).toLocaleDateString("de-DE", { day: "2-digit", month: "2-digit", year: "numeric" }); }
async function nfpArchivWahl() {
  const d = nfpLesen(); if (!nfpGefuellt(d)) return melde("Der Notfallpass ist noch leer.", true);
  if (!(await frage("🗄️ Notfallpass ins Archiv kopieren?\n\nBisher liegt dein Notfallpass nur auf diesem Handy.\nDie Kopie wird in deinem persönlichen Ordner gespeichert – also auch auf dem Vereins-Server, in der Spiegel-Datenbank und in Sicherungen.\n\nSehen kann sie nur du (und wem du deinen Ordner selbst freigibst).\n\nWeiter?"))) return;
  $("nfpInhalt").innerHTML = '<p class="hinweis">Lädt deine Ordner …</p>';
  try { NFP_AR = await api("archiv_liste"); } catch (e) { meldeFehler(e); return nfpZeigen(); }
  const ordner = nfpEigeneOrdner(NFP_AR);
  if (!ordner.length) { melde("Dein persönlicher Ordner ist nicht verfügbar (liegt er im Papierkorb?).", true); return nfpZeigen(); }
  $("nfpInhalt").innerHTML = `<h3 style="margin-top:0">🗄️ In mein Archiv kopieren</h3>
    <label class="feld">Ordner<select id="nfpArOrdner" onchange="nfpArRegister()">${ordner.map((o) => `<option value="${esc(o.id)}">👤 Mein Ordner ${esc(String(o.jahr))}</option>`).join("")}</select></label>
    <label class="feld">Register<select id="nfpArReg"></select></label>
    <p class="hinweis" id="nfpArSchon"></p>
    <p class="hinweis">Gespeichert wird ein Bild des Passes (Stand ${esc(nfpStandText(d))}). Ändert sich etwas, einfach erneut kopieren.</p>
    <button class="knopf haupt" style="text-align:center" onclick="einmal(this, nfpArchivKopieren)">🗄️ Jetzt kopieren</button>
    <button class="knopf" style="text-align:center" onclick="nfpZeigen()">Abbrechen</button>`;
  nfpArRegister();
}
function nfpArRegister() {
  const o = nfpEigeneOrdner(NFP_AR).find((x) => x.id === $("nfpArOrdner").value); if (!o) return;
  const reg = o.register?.length ? o.register : (NFP_AR.register || ["Sonstiges"]);
  const vor = NFP_ARCHIV_REGISTER_VORSCHLAG.find((r) => reg.includes(r)) || reg[0];
  $("nfpArReg").innerHTML = reg.map((r) => `<option${r === vor ? " selected" : ""}>${esc(r)}</option>`).join("");
  const schon = (NFP_AR.dokumente || []).filter((x) => x.ordner_id === o.id && /notfallpass/i.test(x.titel || "")).length;
  $("nfpArSchon").textContent = schon ? `ℹ️ In diesem Ordner liegt schon ${schon === 1 ? "ein Notfallpass" : schon + " Notfallpässe"}. Der alte bleibt liegen – du kannst ihn im Archiv löschen.` : "";
}
function nfpBild(d) {
  // gut lesbares Hochformat-Bild (wie die Anzeige im SOS-Bereich), nur Angaben die ausgefüllt sind
  const B = 1000, R = 48, nf = INIT?.notfall, c = document.createElement("canvas"), g = c.getContext("2d");
  const zeilen = [["Name", ICH?.name || ""], ...NFP_FELDER.filter((f) => String(d[f.k] || "").trim()).map((f) => [f.t, nfpWert(f, String(d[f.k]).trim())])];
  if (nf?.name || nf?.telefon) zeilen.push([`Notfallkontakt${nf.beziehung ? " (" + nf.beziehung + ")" : ""}`, `${nf.name || ""}${nf.telefon ? " · " + nf.telefon : ""}`]);
  const umbrechen = (text, schrift) => {
    g.font = schrift; const aus = [];
    for (const absatz of String(text).split("\n")) {
      let z = "";
      for (const w of absatz.split(" ")) { const t = z ? z + " " + w : w; if (g.measureText(t).width > B - 2 * R - 20 && z) { aus.push(z); z = w; } else z = t; }
      aus.push(z);
    }
    return aus;
  };
  const KLEIN = "28px sans-serif", GROSS = "bold 38px sans-serif";
  const bloecke = zeilen.map(([t, w]) => ({ t, w: umbrechen(w, GROSS) }));
  const H = 190 + bloecke.reduce((s, b) => s + 44 + b.w.length * 48 + 22, 0) + 90;
  c.width = B; c.height = H;
  g.fillStyle = "#ffffff"; g.fillRect(0, 0, B, H);
  g.strokeStyle = "#c0392b"; g.lineWidth = 10; g.strokeRect(14, 14, B - 28, H - 28);
  g.fillStyle = "#c0392b"; g.font = "bold 60px sans-serif"; g.fillText("NOTFALLPASS", R, 110);
  let y = 190;
  for (const b of bloecke) {
    g.fillStyle = "#666666"; g.font = KLEIN; g.fillText(b.t, R, y); y += 44;
    g.fillStyle = "#111111"; g.font = GROSS; for (const z of b.w) { g.fillText(z, R, y); y += 48; }
    g.strokeStyle = "#dddddd"; g.lineWidth = 2; g.beginPath(); g.moveTo(R, y - 20); g.lineTo(B - R, y - 20); g.stroke(); y += 22;
  }
  g.fillStyle = "#666666"; g.font = KLEIN; g.fillText(`Stand: ${nfpStandText(d)} · Köcheclub-App`, R, H - 50);
  return new Promise((ok, nein) => c.toBlob((b) => (b ? ok(b) : nein(new Error("Bild konnte nicht erstellt werden."))), "image/png"));
}
async function nfpArchivKopieren() {
  const d = nfpLesen(), ordner_id = $("nfpArOrdner")?.value, register = $("nfpArReg")?.value;
  if (!nfpGefuellt(d) || !ordner_id) return;
  try {
    const bild = await nfpBild(d), stand = nfpStandText(d);
    await api("archiv_hochladen", { ordner_id, titel: `Notfallpass (Stand ${stand})`, datum: isoBerlin(new Date()), register, stichworte: "Notfallpass, Gesundheit",
      name: `Notfallpass-${stand.replace(/\./g, "-")}.png`, mime: "image/png", daten: base64(await bild.arrayBuffer()) }, { warten: true });
    nfpZu(); melde(`🗄️ Notfallpass liegt jetzt in deinem Ordner (Register „${register}“)`);
    AR.daten = null;
    if ((await frage(`Der Notfallpass liegt jetzt in deinem Ordner, Register „${register}“.\n\nArchiv jetzt öffnen?`))) { AR.ziel = ordner_id; arStart(); }
  } catch (e) { meldeFehler(e); }
}

// ---------- KC-CLUB-WISCHEN (1.6.0, Wunsch Hansi – wie WhatsApp): Nachricht nach rechts wischen = antworten,
// nach links wischen = löschen (mit Sicherheitsabfrage: eigene „für alle“ oder „nur für mich“, fremde „nur für mich“).
// Nur waagerechtes Wischen zählt; senkrechtes Scrollen bleibt unberührt. Am PC: Nachricht antippen → 🗑️ Löschen.
const NA_WISCH = 64;
function naWischenEinrichten() {
  const chat = $("chat"); if (!chat || chat.dataset.wischen) return; chat.dataset.wischen = "1";
  let b = null, x0 = 0, y0 = 0, dx = 0, waagerecht = null;
  chat.addEventListener("touchstart", (e) => {
    const z = e.target.closest(".blase[data-id]"); if (!z || e.touches.length !== 1 || e.target.closest("audio,video,input")) { b = null; return; }
    b = z; x0 = e.touches[0].clientX; y0 = e.touches[0].clientY; dx = 0; waagerecht = null;
  }, { passive: true });
  chat.addEventListener("touchmove", (e) => {
    if (!b) return;
    const mx = e.touches[0].clientX - x0, my = e.touches[0].clientY - y0;
    if (waagerecht === null && (Math.abs(mx) > 10 || Math.abs(my) > 10)) waagerecht = Math.abs(mx) > Math.abs(my) * 1.3;
    if (!waagerecht) return;
    e.preventDefault();
    dx = Math.max(-110, Math.min(110, mx));
    b.style.transform = `translateX(${dx}px)`; b.classList.add("wischt");
    b.dataset.wisch = dx > NA_WISCH ? "antworten" : dx < -NA_WISCH ? "loeschen" : "";
  }, { passive: false });
  const ende = () => {
    if (!b) return;
    const z = b, id = z.dataset.id, was = z.dataset.wisch; b = null;
    z.style.transition = "transform .18s"; z.style.transform = ""; z.dataset.wisch = "";
    setTimeout(() => { z.style.transition = ""; z.classList.remove("wischt"); }, 200);
    if (was === "antworten") { navigator.vibrate?.(15); naAntworten(id); }
    else if (was === "loeschen") { navigator.vibrate?.(15); naLoeschenFragen(id); }
  };
  chat.addEventListener("touchend", ende); chat.addEventListener("touchcancel", ende);
  // ein Wisch soll nicht zusätzlich das Menü (Antippen) öffnen
  chat.addEventListener("click", (e) => { if (Math.abs(dx) > 10) { e.stopPropagation(); e.preventDefault(); dx = 0; } }, true);
}
function naLoeschenFragen(id) {
  const m = NA.nachrichten.get(id); if (!m) return;
  document.getElementById("naLoeschen")?.remove();
  const fuerAlle = m.eigen || ICH?.admin;
  const f = document.createElement("div"); f.id = "naLoeschen"; f.className = "blatt"; f.setAttribute("role", "dialog"); f.setAttribute("aria-modal", "true");
  f.innerHTML = `<div class="blatt-innen">
    <h3 style="margin-top:0">🗑️ Nachricht löschen?</h3>
    <div class="na-vorschau">${m.eigen ? "Du" : esc(m.von)}: ${esc(String(m.text || "📎").slice(0, 120))}</div>
    ${fuerAlle ? `<button class="knopf haupt" onclick="naLoeschen('${id}', true)">🗑️ Für alle löschen</button>` : ""}
    <button class="knopf${fuerAlle ? "" : " haupt"}" onclick="naLoeschen('${id}', false)">🙈 Nur für mich löschen</button>
    <p class="hinweis" style="margin:2px 0 6px">${fuerAlle ? "„Für alle“ entfernt sie bei allen. „Nur für mich“: die anderen sehen sie weiter." : "Die anderen sehen die Nachricht weiter."}</p>
    <button class="knopf" onclick="document.getElementById('naLoeschen').remove()">Abbrechen</button></div>`;
  f.onclick = (e) => { if (e.target === f) f.remove(); };
  document.body.appendChild(f);
}
async function naLoeschen(id, fuerAlle) {
  document.getElementById("naLoeschen")?.remove();
  try { await api(fuerAlle ? "nachricht_loeschen" : "nachricht_ausblenden", { id }); await reisswolf(document.querySelector(`#chat [data-id="${CSS.escape(id)}"]`)); chatStand = ""; melde(fuerAlle ? "🗑️ Für alle gelöscht" : "🙈 Für dich gelöscht"); chatLaden(false); }
  catch (e) { meldeFehler(e); }
}
// KC-CLUB-LOESCHEN: eigene Nachricht für alle löschen; Unterhaltung nur für mich entfernen oder (Admin) für alle löschen
async function nachrichtLoeschen(id) {
  if (!(await frage("Diese Nachricht für alle löschen?"))) return;
  try { await api("nachricht_loeschen", { id }); await reisswolf(document.querySelector(`#chat [data-id="${CSS.escape(id)}"]`)); chatStand = ""; melde("🗑️ Gelöscht"); chatLaden(false); } catch (e) { meldeFehler(e); }
}
