  GR = { id: chat?.id || null, name: chat?.gruppe?.name || "", symbol: chat?.gruppe?.symbol || "👥", personen, vorher: [...personen], ersteller: chat?.gruppe?.erstellt_von || ICH.person_id, admins: [...(chat?.gruppe?.admins || [])] };
