// Druckseite als eigenständiges HTML (Druck-CSS auf „immer“) – für die Vorschau und zum Teilen am iPhone
function druckHtml(vorschau) {
  const css = [...document.styleSheets].flatMap((sh) => { try { return [...sh.cssRules].map((r) => r.cssText); } catch { return []; } }).filter((t) => /#druck|@page/.test(t)).join("\n");
  const blatt = DRUCK.quer ? "297mm" : "210mm";
  // Vorschau: die Druckseite selbst als A4-Blatt (die Druckregel blendet alles außer #druck aus – kein Rahmen drumherum)
  const extra = vorschau ? `html,body{background:#7d7d7d!important} body{margin:0;padding:10px 0} #druck{background:#fff;width:${blatt};min-height:${DRUCK.quer ? "210mm" : "297mm"};margin:0 auto;padding:12mm;box-sizing:border-box;box-shadow:0 4px 18px rgba(0,0,0,.45)}`
    : "body{margin:12mm} .dkopf img{display:none}";
  return `<!doctype html><html lang="de"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>${esc(DRUCK.titel)}</title>
    <style>${css.replace(/@media print\s*\{/, "@media all {")} #druck{display:block!important} ${extra}</style></head><body>${$("druck").outerHTML}</body></html>`;
}
async function druckVorschau() {
  try { if (!(await druckSeiteBauen())) return; } catch (e) { return meldeFehler(e); }
  druckZu();
  const v = $("druckVorschau"), rahmen = $("druckVorschauRahmen");
  $("druckVorschauTitel").textContent = DRUCK.titel || "Vorschau";
  $("druckVorschauAendern").classList.toggle("versteckt", !DRUCKARTEN[DRUCK.art].optionen);
  $("druckVorschauTeilen").classList.toggle("versteckt", !IST_IOS_APP());
  $("druckVorschauHinweis").textContent = IST_IOS_APP() ? "iPhone: Klappt das Drucken aus der App nicht, „📤 Teilen“ antippen und dort drucken oder als PDF sichern." : "Im Druckfenster kannst du auch „Als PDF speichern“ wählen.";
  v.classList.remove("versteckt"); document.body.style.overflow = "hidden";
  // A4-Blatt auf Bildschirmbreite verkleinern (1 mm ≈ 3,78 px)
  const blattPx = (DRUCK.quer ? 297 : 210) * 3.78 + 20, zoom = Math.min(1, (rahmen.clientWidth || innerWidth) / blattPx);
  rahmen.srcdoc = druckHtml(true).replace("</style>", `html{zoom:${zoom.toFixed(3)}}</style>`);
}
function druckVorschauZu() { $("druckVorschau").classList.add("versteckt"); $("druckVorschauRahmen").srcdoc = ""; document.body.style.overflow = ""; }
function druckVorschauAendern() { druckVorschauZu(); druckStarten(DRUCK.art, DRUCK.param); }
// erst hier wird gedruckt – die Druckseite (#druck) ist schon gebaut und entspricht der Vorschau
