  let l = TODO.eintraege.filter((x) => (o.todoErledigte || !x.erledigt) && (o.todoFilter === "alle" || (o.todoFilter === "mir" ? zust(x).some((z) => z.ich) : o.todoFilter === "ich" ? x.fuer === "ich" : x.fuer === "alle")));
  if (!l.length) throw new Error("Keine Aufgaben für diese Auswahl.");
  const gruppen = new Map(), schl = (x) => (o.todoGruppe === "kategorie" ? `${kat(x.kategorie).sym} ${kat(x.kategorie).name}` : o.todoGruppe === "faellig" ? (x.faellig ? (x.faellig < heuteIso() ? "⚠️ überfällig" : "fällig bis " + dz(x.faellig)) : "ohne Termin") : zust(x).length ? "👉 " + zust(x).map((z) => z.vorname).join(", ") : "👉 noch offen – niemand zugewiesen");
