window.addEventListener("appinstalled", () => { installEreignis = null; schonInstalliert = true; lsSetzen("kc_club_als_app", "1"); installStandZeigen(); melde("✅ Köcheclub ist als App installiert – bitte ab jetzt über das neue Symbol öffnen und das alte löschen."); });
