function versionNeuer(a, b) { const x = a.split(".").map(Number), y = b.split(".").map(Number); for (let i = 0; i < 3; i++) { if ((x[i] || 0) !== (y[i] || 0)) return (x[i] || 0) > (y[i] || 0); } return false; }
const UPDATE_TAKT_MS = 10 * 60000; // KC-CLUB-UPDATE-AUTO (2.3.2)
let NEUE_VERSION = null, VERSION_INFO = null; // Version auf GitHub, falls neuer als die installierte
