async function jetztAktualisieren() {
  VB.update = true; vbStatusLed(); // blaue LED: Wartung/Update läuft
  try { localStorage.setItem("kc_club_neustart_update", "1"); } catch {} // KC-CLUB-FEHLERPROTOKOLL: kein Fehlalarm „mehrfach geöffnet“
  let fertig = false; const neu = () => { if (!fertig) { fertig = true; location.reload(); } };
  // 2.97.0 KC-CLUB-UPDATE-FRIST (Fund Hansi, iPad: blaue LED, Update hing nach langer Pause im Hintergrund): iOS beantwortet
  // getRegistration()/update() manchmal nie → jeder Schritt hat eine Frist, und spätestens nach 30 s wird neu geladen
  const mitFrist = (p, ms) => Promise.race([Promise.resolve(p).catch(() => null), new Promise((ok) => setTimeout(() => ok(null), ms))]);
  setTimeout(neu, 30000);
  try {
    const reg = await mitFrist(navigator.serviceWorker?.getRegistration(), 5000);
    if (reg) {
      navigator.serviceWorker.addEventListener("controllerchange", neu, { once: true });
      await mitFrist(reg.update(), 10000);
      const sw = reg.installing;
      if (sw) await new Promise((ok) => { const t = setTimeout(ok, 15000); sw.addEventListener("statechange", () => { if (sw.state !== "installing") { clearTimeout(t); ok(); } }); });
      if (reg.waiting) { reg.waiting.postMessage("jetzt-aktivieren"); setTimeout(neu, 4000); return; }
    }
  } catch {}
  neu();
}
// Beim Zurückholen der App: gibt es eine neue Version und wird gerade nichts eingegeben, aktualisiert die App sich selbst –
// höchstens einmal je 10 Min. und Version (Schutz vor Endlosschleife, falls der Server kurz noch die alte Seite liefert)
function updateRuhig() {
  if (RUF || SPR || wartenZahl) return false; // 2.1.1: nie während Anruf, Sprachaufnahme oder laufender Übertragung
  if (document.querySelector(".blatt:not(.versteckt)")) return false;
  const a = document.activeElement; if (a && /^(INPUT|TEXTAREA|SELECT)$/.test(a.tagName)) return false;
  return !etwasGetippt();
}
const etwasGetippt = () => [...document.querySelectorAll("textarea, input[type=text], input:not([type])")].some((el) => el.offsetParent && el.value.trim());
// KC-CLUB-UPDATE-START (2.24.2, Wunsch Hansi, Fund: Update kam bei kurzen Besuchen erst beim übernächsten Öffnen an):
// gleich nach dem Öffnen (erste 20 s, auch beim Zurückholen nach ≥ 2 Min.) und solange noch nichts angetippt/getippt wurde,
// lädt die App ein gefundenes Update SOFORT – auch wenn die App selbst schon ein Fenster/Hinweis geöffnet hat.
// Mitten in der Benutzung bleibt alles wie bisher (updateRuhig + Startseite); Schleifenschutz unverändert.
const UPDATE_START_MS = 20000, UPDATE_WEG_MS = 120000;
let UPD_FRISCH = Date.now(), UPD_WEG = 0;
["pointerdown", "keydown"].forEach((t) => addEventListener(t, () => { UPD_FRISCH = 0; }, { capture: true, passive: true }));
const updateFrisch = () => !!UPD_FRISCH && Date.now() - UPD_FRISCH < UPDATE_START_MS;
function updWeg(versteckt) { if (versteckt) UPD_WEG = Date.now(); else if (UPD_WEG && Date.now() - UPD_WEG >= UPDATE_WEG_MS) { UPD_FRISCH = Date.now(); UPD_WEG = 0; } }
// 2.6.1 (Prüfung): nur wenn angemeldet, auf der Startseite, kein Chat/Anruf/Sprunglink offen; ohne funktionierenden Speicher nie
// (sonst Endlosschleife/Abmeldung); schon einmal von DIESER Version aus versucht und immer noch alt → 6 Std. Pause + Meldung
const UPDATE_PAUSE_MS = 10 * 60000, UPDATE_MISSLUNGEN_MS = 6 * 3600000;
function updateSelbst() {
  const frisch = updateFrisch(); // KC-CLUB-UPDATE-START: direkt nach dem Öffnen, noch nichts angetippt
  if (!NEUE_VERSION || RUF || SPR || wartenZahl || /#(anruf|anklopfen)=/.test(START_HASH || "") && Date.now() - (window.KCFP?.start || 0) < 120000) return;
  if (frisch ? etwasGetippt() : (!updateRuhig() || !ICH || aktuelleAnsicht !== "start" || chatId || RUF)) return;
  let z = {}; try { z = JSON.parse(localStorage.getItem("kc_club_auto_update") || "{}") || {}; } catch {}
  const nochmal = z.v === NEUE_VERSION && z.von === APP_VERSION;
  if (nochmal && Date.now() - z.t < (z.misslungen ? UPDATE_MISSLUNGEN_MS : UPDATE_PAUSE_MS)) return;
  if (nochmal && !z.misslungen) { z.misslungen = true; z.t = Date.now(); try { localStorage.setItem("kc_club_auto_update", JSON.stringify(z)); } catch {} fpNeu("update_misslungen", { hat: APP_VERSION, neu: NEUE_VERSION }); return; }
  const neu = JSON.stringify({ v: NEUE_VERSION, von: APP_VERSION, t: Date.now() });
  try { localStorage.setItem("kc_club_auto_update", neu); if (localStorage.getItem("kc_club_auto_update") !== neu) return; } catch { return; }
  fpNeu(frisch ? "update_start" : "update_selbst", { hat: APP_VERSION, neu: NEUE_VERSION }); melde(`🔄 Neue Version ${NEUE_VERSION} – wird geladen …`); jetztAktualisieren();
}

// ---------- KC-CLUB-NUTZUNG (0.99.0): Nutzungsstatistik OHNE Namen ----------
// Gezählt wird nur, wie oft ein Bereich geöffnet wird – auf dem Gerät gesammelt, alle 2 Minuten gebündelt geschickt.
// Der Server speichert nur Tag + Bereich + Anzahl, nie wer.
// ---------- KC-CLUB-ARCHIV (1.2.0, Wunsch Hansi): Regal mit Aktenordnern (Jahreszahl + Inhalt), innen Register ----------
// Automatisch: „Clubleben JJJJ“ je Jahr aus vorhandenen Daten (nur lesen). Von Hand: Ordner mit Art, Jahr, Farbe, Registern.
// Pflegen (Ordner, Hochladen, Ändern, Löschen): Clubsprecher und Admin – der Server prüft das.
// KC-CLUB-ARCHIV-UNTERREGISTER (2.147.0, Wunsch Hansi „Ordner Weihnachtsmarkt mit Registern 2026, 2027 … und darunter z. B. Checklisten“):
// Ein Register „2026 › Checklisten“ ist ein Unterregister von „2026“. Oben stehen die Jahre, darunter die Unterregister des gewählten Jahres.
// Ein Ordner mit solchen Registern gilt als mehrjährig – sein Name kommt ohne Jahreszahl (das Jahr steckt im Register).
const AR_TRENN = " › ";
const arMehrjahr = (o) => (o?.register || []).some((r) => String(r).includes(AR_TRENN));
const arName = (o) => (arMehrjahr(o) || o?.art === "chronik" ? o.titel : `${o.titel} ${o.jahr}`);
const arJahrSpanne = (o) => { const j = [...new Set((o.register || []).map((r) => String(r).split(AR_TRENN)[0]).filter((x) => /^\d{4}$/.test(x)))].sort(); return j.length ? (j.length > 1 ? `${j[0]}–${j[j.length - 1]}` : j[0]) : String(o.jahr); };
const arImRegister = (x, reg) => !reg || x.register === reg || String(x.register || "").startsWith(reg + AR_TRENN);
const AR_FARBEN = ["#8b1e2d", "#1f5f99", "#2e7d4f", "#b36b00", "#5b3f8c", "#3f4a54", "#0f7c80", "#a33b6b"];
const AR_AUTO = { treffen: ["📅", "Termine"], protokoll: ["📄", "Protokolle"], abstimmung: ["🗳️", "Abstimmungen"], aktion: ["🧳", "Aktionen"], pinnwand: ["📌", "Pinnwand"], anhang: ["📎", "Anhänge"], dienst: ["🗓️", "Dienste"] };
let AR = { ziel: null, daten: null, ordner: null, register: "", suche: "", jahr: "", art: "", korb: false, datei: null };
try { const f = JSON.parse(localStorage.getItem("kc_club_archiv_filter") || "null"); if (f) { AR.jahr = f.jahr || ""; AR.art = f.art || ""; } } catch {}
const arFilterMerken = () => { try { localStorage.setItem("kc_club_archiv_filter", JSON.stringify({ jahr: AR.jahr, art: AR.art })); } catch {} };
function arStart() { AR.ordner = null; AR.korb = false; AR.suche = ""; zeige("archiv"); }
// 1.65.0: direkt einen Ordner einer Art öffnen (z. B. die Chronik aus dem Büro-Regal); fehlt er, bleibt das Regal offen
function arStartArt(art) { AR.zielArt = art; arStart(); }
function arStartTitel(titel) { AR.zielTitel = titel; arStart(); } // Club-Ordner nach Beschriftung öffnen (neuester Jahrgang)
async function arLaden() {
  if (!AR.daten) $("arInhalt").innerHTML = '<p class="hinweis">Lädt …</p>';
  try { AR.daten = await api("archiv_liste");
    if (AR.zielArt) { const za = AR.daten.ordner.find((o) => !o.besitzer && o.art === AR.zielArt); AR.zielArt = null; if (za) return arOrdnerOeffnen(za.id); }
    if (AR.zielTitel) { const zt = AR.daten.ordner.filter((o) => !o.besitzer && o.titel === AR.zielTitel).sort((a, b) => b.jahr - a.jahr)[0]; const t = AR.zielTitel; AR.zielTitel = null; if (zt) return arOrdnerOeffnen(zt.id); melde(`Den Ordner „${t}“ gibt es noch nicht – im Archiv mit „＋“ anlegen.`, true); }
    if (AR.ziel) { const z = AR.ziel, zr = AR.zielRegister; AR.ziel = null; AR.zielRegister = "";
      if (AR.daten.ordner.some((o) => o.id === z) || (String(z).startsWith("auto:") && arAlleOrdner().some((o) => o.id === z))) { arOrdnerOeffnen(z); if (zr) { AR.register = zr; arZeigen(); } return; } } arZeigen(); } catch (e) { $("arInhalt").innerHTML = `<div class="karte hinweis">⚠️ ${esc(fehlerText(e))}</div>`; }
}
const arJahr = (datum) => String(datum || "").slice(0, 4);
const arAutoOrdner = (jahr) => ({ id: "auto:" + jahr, auto: true, jahr: Number(jahr), titel: "Clubleben", farbe: 0, register: Object.keys(AR_AUTO).map((k) => AR_AUTO[k][1]) });
function arAlleOrdner() {
  const d = AR.daten, jahre = [...new Set(d.auto.map((x) => arJahr(x.datum)))];
  return [...jahre.map(arAutoOrdner), ...d.ordner];
}
const arFarbe = (o) => o.auto ? "#6b5b53" : AR_FARBEN[(o.farbe || 1) - 1] || AR_FARBEN[0];
const arSym = (o) => o.auto ? "🤖" : o.besitzer ? (o.eigen ? "👤" : "🤝") : AR.daten.arten[o.art]?.sym || "🗂️";
