  if (AR.art === "alben") return false; // KC-CLUB-FOTO-ALBEN: nur Fotoalben zeigen
  if (AR.jahr && String(o.jahr) !== AR.jahr) return false;
  if (AR.art === "auto") return !!o.auto;
