  const eigene = d.ordner.filter((o) => o.eigen).sort((a, b) => b.jahr - a.jahr), geteilt = d.ordner.filter((o) => o.besitzer && !o.eigen);
  const sp = d.speicher || { belegt: 0, grenze: 1 };
  const pers = `<div class="abschnitt ar-pers"><h3>👤 Mein Ordner</h3><button class="knopf klein" onclick="arNeuesJahr()">＋ weiteres Jahr</button></div>
      <div class="regal">${eigene.map(arRuecken).join("")}${arAlben(true).map(arAlbumRuecken).join("")}</div>
      <p class="hinweis" style="margin:2px 6px 10px">🔒 Nur du siehst deine Ordner – auch der Admin nicht. Mit 🔓 kannst du anderen etwas auf Zeit freigeben. Belegt: ${arGroesse(sp.belegt) || "0 KB"} von ${arGroesse(sp.grenze)}.</p>`
    + (geteilt.length ? `<div class="abschnitt"><h3>🤝 Mit mir geteilt</h3></div><div class="regal">${geteilt.map(arRuecken).join("")}</div>` : "");
  // KC-CLUB-CHRONIK (1.64.0): die Clubchronik steht über allen Jahren (ein Ordner für alle Jahre)
  const chroniken = d.ordner.filter((o) => !o.besitzer && o.art === "chronik" && (!AR.art || AR.art === "chronik"));
  const chronikTeil = chroniken.length ? `<div class="abschnitt"><h3>📖 Clubchronik</h3></div><div class="regal">${chroniken.map(arRuecken).join("")}</div>`
    : d.darf && !AR.art && !AR.jahr ? `<div class="karte hinweis" style="display:flex;gap:10px;align-items:center;flex-wrap:wrap">📖 <span style="flex:1;min-width:180px">Noch keine <b>Clubchronik</b>. Ein Ordner für alle Jahre – alle dürfen Beiträge einreichen.</span><button class="knopf klein haupt" onclick="arChronikAnlegen()">📖 Chronik anlegen</button></div>` : "";
  const ordner = arAlleOrdner().filter((o) => !o.besitzer && arPasst(o) && o.art !== "chronik");
  const alben = arAlben(false).filter((a) => (!AR.jahr || String(a.jahr) === AR.jahr) && (!AR.art || AR.art === "alben")); // KC-CLUB-FOTO-ALBEN
  const jahre = [...new Set([...ordner.map((o) => o.jahr), ...alben.map((a) => a.jahr)])].sort((a, b) => b - a);
  const verein = !ordner.length && !alben.length
