  const doks = d.dokumente.filter((x) => x.ordner_id === oid && x.status !== "pruefung");
  const tag = (n) => isoBerlin(new Date(Date.now() + n * 86400000)); // 2.0.0: Berliner Tag (vorher UTC → kurz nach Mitternacht falsch)
