    const r = await api("archiv_freigeben", { ordner_id: oid, register: w.startsWith("r:") ? w.slice(2) : undefined, dokument_id: w.startsWith("d:") ? w.slice(2) : undefined,
      personen, gruppen, bis: bis.toISOString(), hochladen: $("frHoch").checked });
    arBlattZu(); melde(`🔓 Freigegeben – ${r.benachrichtigt} ${r.benachrichtigt === 1 ? "Person" : "Personen"} benachrichtigt`); await arLaden();
