// ----- Papierkorb -----
async function arKorbZeigen() {
  $("arInhalt").innerHTML = '<p class="hinweis">Lädt …</p>';
  try {
    const k = await api("archiv_papierkorb");
    const bis = (x) => `endgültig weg am ${fTagDe(x.endgueltig_am.slice(0, 10))}`;
    // 1.19.0: ❌ endgültig löschen (einzeln oder alles) – macht den Speicher sofort frei
    const alle = [...k.ordner.map((o) => ({ ordner: o.id })), ...k.dokumente.map((x) => ({ id: x.id }))];
    AR.korbAlle = alle;
    $("arInhalt").innerHTML = `<p class="hinweis">Gelöschtes wird ${AR.daten.papierkorbTage} Tage nach dem Löschen endgültig entfernt. ♻️ holt es zurück, ❌ löscht sofort endgültig (Speicher wird frei).</p>
      ${alle.length ? '<div class="knoepfe" style="margin:0 0 8px"><button class="knopf klein" onclick="arKorbLeeren(AR.korbAlle)">❌ Papierkorb leeren</button></div>' : ""}
      <div class="ar-blatt">${[...k.ordner.map((o) => `<div class="ar-dok"><span class="sym">🗄️</span><div><b>Ordner ${esc(o.titel)} ${o.jahr}</b><div class="hinweis">${bis(o)}</div></div><span class="ar-dok-knoepfe"><button class="knopf klein" title="Wiederherstellen" onclick="arWiederher({ordner:'${o.id}'})">♻️</button><button class="knopf klein" title="Endgültig löschen" onclick="arEndgueltig({ordner:'${o.id}'}, ${esc(JSON.stringify("Ordner " + o.titel + " " + o.jahr))})">❌</button></span></div>`),
        ...k.dokumente.map((x) => `<div class="ar-dok"><span class="sym">📄</span><div><b>${esc(x.titel)}</b><div class="hinweis">${esc(x.ordner)} · ${bis(x)}</div></div><span class="ar-dok-knoepfe"><button class="knopf klein" title="Wiederherstellen" onclick="arWiederher({id:'${x.id}'})">♻️</button><button class="knopf klein" title="Endgültig löschen" onclick="arEndgueltig({id:'${x.id}'}, ${esc(JSON.stringify(x.titel))})">❌</button></span></div>`)].join("")
        || (AR.daten.autoWeg?.length ? "" : '<p class="hinweis" style="margin:6px">Der Papierkorb ist leer.</p>')}</div>
      ${AR.daten.autoWeg?.length ? `<div class="abschnitt" style="margin-top:12px"><h3>🤖 Aus dem Clubleben entfernt</h3></div><div class="ar-blatt">${AR.daten.autoWeg.map((x) => `<div class="ar-dok"><span class="sym">${AR_AUTO[x.art]?.[0] || "📄"}</span><div><b>${esc(x.titel)}</b><div class="hinweis">${esc(arTag(x.datum))} · nur für dich ausgeblendet</div></div><span class="ar-dok-knoepfe"><button class="knopf klein" title="Zurückholen" onclick="arEinblenden('${x.art}', ${esc(JSON.stringify(x.id))})">♻️</button></span></div>`).join("")}</div>` : ""}`;
  } catch (e) { meldeFehler(e); }
}
// KC-CLUB-ARCHIV-AUSBLENDEN (1.64.2, Wunsch Hansi „Löschen muss in allen Ordnern möglich sein“): im Clubleben entfernen.
// Standard: nur für mich ausblenden (Termine, Protokolle … gehören anderen Bereichen und bleiben). Eigene Chat-Anlage: wahlweise
// auch die Nachricht im Chat löschen (vorhandener Weg nachricht_loeschen, mit Sicherung). Zurückholen: Archiv → 🗑️ Papierkorb.
async function arAusblenden(x) {
  const nur = async () => { await api("archiv_ausblenden", { art: x.art, id: x.id }); melde("🗑️ Aus dem Clubleben entfernt – im Papierkorb zurückholbar"); await arLaden(); };
  if (x.art === "anhang" && x.vonMir && x.nachricht) {
    const f = blattAuf("arWegBlatt", `<h3 style="margin-top:0">🗑️ „${esc(x.titel)}“ entfernen?</h3>
      <p class="hinweis">Die Datei hast du in einem Chat verschickt.</p>
      <div class="knoepfe" style="flex-direction:column;align-items:stretch"><button class="knopf haupt" data-w="nur">🗄️ Nur hier im Archiv entfernen</button>
        <button class="knopf dlg-gefahr" data-w="chat">💬 Auch im Chat löschen (für alle im Chat)</button><button class="knopf" data-w="zu">Abbrechen</button></div>`);
    f.querySelectorAll("[data-w]").forEach((b) => (b.onclick = async () => { f.remove();
      try { if (b.dataset.w === "nur") await nur();
        else if (b.dataset.w === "chat") { await api("nachricht_loeschen", { id: x.nachricht }); melde("🗑️ Im Chat gelöscht"); await arLaden(); } } catch (e) { meldeFehler(e); } }));
    return;
  }
  if (!(await frage(`„${x.titel}“ aus dem Clubleben entfernen?\nNur für dich – im eigentlichen Bereich (Termine, Protokolle …) bleibt alles. Zurückholen im 🗑️ Papierkorb.`, { ja: "🗑️ Entfernen" }))) return;
  try { await nur(); } catch (e) { meldeFehler(e); }
}
async function arEinblenden(art, id) { try { await api("archiv_ausblenden", { art, id, zurueck: true }); melde("♻️ Wieder im Clubleben"); await arLaden(); arKorbZeigen(); } catch (e) { meldeFehler(e); } }
async function arWiederher(was) {
  try { await api("archiv_wiederherstellen", was); melde("♻️ Wiederhergestellt"); await arLaden(); arKorbZeigen(); } catch (e) { meldeFehler(e); }
}

