function fpHinweisPruefen() {
  if (document.getElementById("fpFenster")) return;
  const h = FP_HINWEISE.find((x) => { try { return x.wenn(); } catch { return false; } });
  if (!h) return;
  const heute = isoBerlin(new Date()); // 2.0.0: Berliner Tag
  try { const z = localStorage.getItem("kc_club_hinweis_" + h.id);
    if (z === heute || (h.abstandTage && z && (Date.parse(heute) - Date.parse(z)) / 86400000 < h.abstandTage)) return; localStorage.setItem("kc_club_hinweis_" + h.id, heute); } catch {}
  fpNeu("hinweis", { id: h.id, browser: fpBrowser(), system: fpSystem(), start: START_ART, text: "Hilfe gezeigt: " + h.titel });
  const schritte = typeof h.schritte === "function" ? h.schritte() : h.schritte;
  const f = document.createElement("div"); f.id = "fpFenster"; f.className = "blatt"; f.setAttribute("role", "dialog"); f.setAttribute("aria-modal", "true");
  f.innerHTML = `<div class="blatt-innen" style="max-height:88vh;overflow-y:auto">
    <h3>${h.titel}</h3><p style="margin:0">${h.text()}</p>
    <ol class="fp-schritte">${schritte.map((x) => `<li>${x}</li>`).join("")}</ol>
    ${h.link && KEY ? `<button class="knopf haupt" onclick="fpLinkKopieren()">🔗 Meinen Link kopieren</button>` : ""}
    ${h.melden ? `<button class="knopf" onclick="document.getElementById('fpFenster').remove();fpProblemMelden()">🆘 Problem melden</button>` : ""}
    <button class="knopf" onclick="document.getElementById('fpFenster').remove()">Verstanden</button></div>`;
  document.body.appendChild(f);
}
async function fpLinkKopieren() {
  const link = APP_URL_CLUB + "?k=" + KEY;
  let ok = false; try { await navigator.clipboard.writeText(link); ok = true; } catch {}
  if (!ok) { try { const t = document.createElement("textarea"); t.value = link; document.body.appendChild(t); t.select(); ok = document.execCommand("copy"); t.remove(); } catch {} }
  fpNeu("link_kopiert", { ok });
  melde(ok ? "🔗 Dein Link ist kopiert – jetzt in Safari/Chrome oben einfügen" : "Kopieren ging nicht – bitte den Link aus deiner Mail/WhatsApp nehmen", !ok);
}
async function fpProblemMelden() {
  const text = (await eingabe("Was klappt nicht? (freiwillig, ein paar Worte reichen)\n\n" + adminName() + " bekommt eine Nachricht und sieht automatisch, welches Handy, welcher Browser und welche Version du hast.", ""));
  if (text === null) return;
  try { window.KCFP?.senden(true); } catch {}
  if (!INIT) { fpNeu("hilferuf_anonym", { text: text.trim(), browser: fpBrowser(), system: fpSystem() }); window.KCFP?.senden(true); return melde("🆘 Deine Meldung ist unterwegs – " + adminName() + " meldet sich."); }
  try { await api("hilfe_anfordern", { text: text.trim(), info: { system: fpSystem(), browser: fpBrowser(), start: START_ART, speicher: !!window.KCFP?.speicherOk,
    push: "Notification" in window ? Notification.permission : "nicht_moeglich", online: navigator.onLine, bildschirm: `${screen.width}x${screen.height}`, sicht: aktuelleAnsicht } });
    melde("🆘 Danke – " + adminName() + " hat deine Meldung bekommen und meldet sich."); }
  catch (e) { meldeFehler(e); }
}
